function clearHarvestEquipmentDragPreview() {
  if (activeHarvestEquipmentDragPreview?.parentNode) {
    activeHarvestEquipmentDragPreview.parentNode.removeChild(activeHarvestEquipmentDragPreview);
  }
  activeHarvestEquipmentDragPreview = null;
}

function createHarvestEquipmentDragPreview(sourceNode) {
  if (typeof document === 'undefined' || !sourceNode) return null;
  clearHarvestEquipmentDragPreview();
  const preview = sourceNode.cloneNode(true);
  preview.style.position = 'fixed';
  preview.style.left = '-9999px';
  preview.style.top = '-9999px';
  preview.style.margin = '0';
  preview.style.pointerEvents = 'none';
  preview.style.opacity = '1';
  preview.style.transform = 'none';
  preview.style.boxShadow = '0 12px 24px rgba(25, 74, 57, 0.16)';
  preview.style.zIndex = '2147483647';
  document.body.appendChild(preview);
  activeHarvestEquipmentDragPreview = preview;
  return preview;
}
