const PHONE_HELPER_CONTACT_KEYS = Object.keys(PHONE_HELPER_CONTACTS);

const PHONE_HELPER_SUMMARY_MAX_LENGTH = 700;

const summarizePhoneHelperThread = (messages = []) => {
  const rows = (Array.isArray(messages) ? messages : [])
    .filter((entry) => entry && (entry.role === 'user' || entry.role === 'assistant'))
    .slice(-6)
    .map((entry) => {
      const speaker = entry.role === 'user' ? '사용자' : '상담사';
      const text = String(entry.text || '').replace(/\s+/g, ' ').trim();
      if (!text) return '';
      return `${speaker}: ${text}`;
    })
    .filter(Boolean);
  if (!rows.length) return '';
  return rows.join(' / ');
};

const mergePhoneHelperConversationSummaries = (prevSummary = '', daySummary = '') => {
  const summaryParts = [String(prevSummary || '').trim(), String(daySummary || '').trim()].filter(Boolean);
  if (!summaryParts.length) return '';
  const merged = summaryParts.join(' || ');
  return merged.length > PHONE_HELPER_SUMMARY_MAX_LENGTH
    ? merged.slice(merged.length - PHONE_HELPER_SUMMARY_MAX_LENGTH)
    : merged;
};

const rollPhoneHelperMemoryToNextDay = (gameState) => {
  const normalizedThreads = normalizeAppleHelperChatThreads(gameState?.appleHelperChatMessages || {});
  const previousSummaryByContact = gameState?.phoneHelperConversationSummaryByContact || {};
  const nextSummaryByContact = {};

  PHONE_HELPER_CONTACT_KEYS.forEach((contactKey) => {
    const daySummary = summarizePhoneHelperThread(normalizedThreads[contactKey] || []);
    const mergedSummary = mergePhoneHelperConversationSummaries(previousSummaryByContact?.[contactKey], daySummary);
    if (mergedSummary) {
      nextSummaryByContact[contactKey] = mergedSummary;
    }
  });

  return {
    ...gameState,
    appleHelperChatMessages: Object.fromEntries(PHONE_HELPER_CONTACT_KEYS.map((contactKey) => [contactKey, []])),
    phoneHelperConversationSummaryByContact: nextSummaryByContact
  };
};

