const CREW_DAILY_LIMIT_RANGE = {
  beginner: { min: 5, max: 15 },
  worker: { min: 5, max: 20 },
  skilledWorker: { min: 2, max: 8 },
  agriTechnician: { min: 1, max: 4 }
};
const DAILY_ASSIGNMENT_TASK_LABEL = Object.freeze({
  harvest: '수확',
  transport: '운반'
});
const createEmptyCrewTypeMap = () => CREW_TYPE_KEYS.reduce((acc, key) => ({ ...acc, [key]: 0 }), {});
const createEmptyDailyAssignmentLocks = (day = 1) => ({
  day: Math.max(1, Math.floor(Number(day) || 1)),
  laborByWorkerKey: {},
  equipmentByTokenId: {}
});
const normalizeHarvestTransportAssignmentShape = (raw) => ({
  useSelfLabor: Boolean(raw?.useSelfLabor),
  selectedWorkerIdsByType: {
    beginner: Array.from(new Set((raw?.selectedWorkerIdsByType?.beginner || []).map((id) => String(id || '')).filter(Boolean))),
    worker: Array.from(new Set((raw?.selectedWorkerIdsByType?.worker || []).map((id) => String(id || '')).filter(Boolean))),
    skilledWorker: Array.from(new Set((raw?.selectedWorkerIdsByType?.skilledWorker || []).map((id) => String(id || '')).filter(Boolean)))
  }
});
const normalizeDailyAssignmentLocks = (raw, currentDay = 1) => {
  const safeDay = Math.max(1, Math.floor(Number(currentDay) || 1));
  const sourceDay = Math.max(0, Math.floor(Number(raw?.day) || 0));
  if (!raw || sourceDay !== safeDay) return createEmptyDailyAssignmentLocks(safeDay);
  const next = createEmptyDailyAssignmentLocks(safeDay);
  Object.entries(raw?.laborByWorkerKey || {}).forEach(([workerKeyRaw, entry]) => {
    const workerKey = String(workerKeyRaw || '');
    const taskGroup = String(entry?.taskGroup || '');
    if (!workerKey || !DAILY_ASSIGNMENT_TASK_LABEL[taskGroup]) return;
    const equipmentTokenIds = Array.from(new Set(
      (Array.isArray(entry?.equipmentTokenIds) ? entry.equipmentTokenIds : [])
        .map((tokenId) => String(tokenId || ''))
        .filter(Boolean)
    ));
    next.laborByWorkerKey[workerKey] = {
      day: safeDay,
      taskGroup,
      equipmentTokenIds
    };
  });
  Object.entries(raw?.equipmentByTokenId || {}).forEach(([tokenIdRaw, entry]) => {
    const tokenId = String(tokenIdRaw || '');
    const taskGroup = String(entry?.taskGroup || '');
    if (!tokenId || tokenId === 'manual:carry' || !DAILY_ASSIGNMENT_TASK_LABEL[taskGroup]) return;
    const workerKeys = Array.from(new Set(
      (Array.isArray(entry?.workerKeys) ? entry.workerKeys : [])
        .map((workerKey) => String(workerKey || ''))
        .filter(Boolean)
    ));
    next.equipmentByTokenId[tokenId] = {
      day: safeDay,
      taskGroup,
      workerKeys,
      transportAssignment: taskGroup === 'transport'
        ? normalizeHarvestTransportAssignmentShape(entry?.transportAssignment)
        : null
    };
  });
  return next;
};
const buildDailyWorkerKey = ({ kind = 'worker', typeKey = '', workerId = '', selfWorkerId = 'self' } = {}) => {
  const normalizedWorkerId = String(workerId || '');
  if (!normalizedWorkerId) return '';
  if (kind === 'self' || normalizedWorkerId === String(selfWorkerId || 'self')) return 'self';
  const normalizedTypeKey = String(typeKey || '');
  if (!normalizedTypeKey) return '';
  return `worker:${normalizedTypeKey}:${normalizedWorkerId}`;
};
const dailyAssignmentTaskLabelOf = (taskGroupRaw) => DAILY_ASSIGNMENT_TASK_LABEL[String(taskGroupRaw || '')] || '작업';
const buildDailyWorkerLockReason = (lockEntry) => (
  lockEntry
    ? `오늘 이미 ${dailyAssignmentTaskLabelOf(lockEntry.taskGroup)} 작업에 배정된 인원입니다.`
    : ''
);
const buildDailyEquipmentLockReason = (lockEntry) => (
  lockEntry
    ? `이 장비는 오늘 이미 ${dailyAssignmentTaskLabelOf(lockEntry.taskGroup)} 작업에 사용했습니다.`
    : ''
);
const canReuseWorkerForHarvestOnSameDay = (lockEntry) => (
  String(lockEntry?.taskGroup || '') === 'harvest'
);
const canReuseEquipmentForHarvestOnSameDay = (lockEntry) => (
  String(lockEntry?.taskGroup || '') === 'harvest'
);
const applyDailyAssignmentLocksToGame = (prevState, { taskGroup = '', workerEntries = [], equipmentTokenIds = [] } = {}) => {
  const normalizedTaskGroup = String(taskGroup || '');
  if (!DAILY_ASSIGNMENT_TASK_LABEL[normalizedTaskGroup]) return prevState;
  const nextLocks = normalizeDailyAssignmentLocks(prevState?.dailyAssignmentLocks, prevState?.day);
  const normalizedWorkerEntries = (Array.isArray(workerEntries) ? workerEntries : [])
    .map((entry) => ({
      workerKey: String(entry?.workerKey || ''),
      equipmentTokenIds: Array.from(new Set(
        (Array.isArray(entry?.equipmentTokenIds) ? entry.equipmentTokenIds : [])
          .map((tokenId) => String(tokenId || ''))
          .filter(Boolean)
      ))
    }))
    .filter((entry) => entry.workerKey);
  const normalizedEquipmentTokenIds = Array.from(new Set(
    (Array.isArray(equipmentTokenIds) ? equipmentTokenIds : [])
      .map((tokenId) => String(tokenId || ''))
      .filter(Boolean)
  ));
  normalizedWorkerEntries.forEach((entry) => {
    const existing = nextLocks.laborByWorkerKey[entry.workerKey];
    nextLocks.laborByWorkerKey[entry.workerKey] = {
      day: nextLocks.day,
      taskGroup: normalizedTaskGroup,
      equipmentTokenIds: Array.from(new Set([
        ...(existing?.equipmentTokenIds || []),
        ...entry.equipmentTokenIds
      ]))
    };
  });
  normalizedEquipmentTokenIds.forEach((tokenId) => {
    const existing = nextLocks.equipmentByTokenId[tokenId];
    nextLocks.equipmentByTokenId[tokenId] = {
      day: nextLocks.day,
      taskGroup: normalizedTaskGroup,
      workerKeys: Array.from(new Set([
        ...(existing?.workerKeys || []),
        ...normalizedWorkerEntries
          .filter((entry) => entry.equipmentTokenIds.includes(tokenId))
          .map((entry) => entry.workerKey)
      ]))
    };
  });
  return {
    ...prevState,
    dailyAssignmentLocks: nextLocks
  };
};
const applyHarvestTransportEquipmentLockToGame = (prevState, {
  equipmentKey = '',
  assignment = null
} = {}) => {
  const normalizedEquipmentKey = String(equipmentKey || '');
  if (!normalizedEquipmentKey || normalizedEquipmentKey === 'manual:carry') return prevState;
  const nextLocks = normalizeDailyAssignmentLocks(prevState?.dailyAssignmentLocks, prevState?.day);
  nextLocks.equipmentByTokenId[normalizedEquipmentKey] = {
    day: nextLocks.day,
    taskGroup: 'transport',
    workerKeys: [],
    transportAssignment: normalizeHarvestTransportAssignmentShape(assignment)
  };
  return {
    ...prevState,
    dailyAssignmentLocks: nextLocks
  };
};
const createCrewDraftState = (start = inputDate(1), end = inputDate(7)) =>
  CREW_TYPE_KEYS.reduce((acc, key) => ({
    ...acc,
    [key]: { count: 1, start, end }
  }), {});
const normalizeCrewCountMap = (raw = {}, legacyMap = {}) => {
  const next = createEmptyCrewTypeMap();
  CREW_TYPE_KEYS.forEach((key) => {
    next[key] = Math.max(0, Math.floor(Number(raw?.[key]) || 0));
  });
  Object.entries(legacyMap || {}).forEach(([legacyKey, nextKey]) => {
    if (!CREW_TYPE_KEYS.includes(nextKey)) return;
    next[nextKey] += Math.max(0, Math.floor(Number(raw?.[legacyKey]) || 0));
  });
  return next;
};
