const normalizeCrewWorkerNames = (workerNames) =>
  (Array.isArray(workerNames) ? workerNames : [])
    .map((name) => String(name || '').trim())
    .filter(Boolean);
const normalizeCrewWorkerGenders = (workerGenders, workerNames = []) => {
  const names = normalizeCrewWorkerNames(workerNames);
  return (Array.isArray(workerGenders) ? workerGenders : [])
    .map((gender, index) => {
      const rawGender = String(gender || '').trim();
      if (['male', 'female', 'neutral'].includes(rawGender)) return rawGender;
      return crewGenderOfName(names[index]);
    })
    .filter(Boolean);
};
const assignCrewProfilesForContract = (rent, usedNames = new Set()) => {
  const normalizedCount = Math.max(1, Math.floor(Number(rent?.count) || 0));
  const existingNames = normalizeCrewWorkerNames(rent?.workerNames);
  const existingGenders = normalizeCrewWorkerGenders(rent?.workerGenders, existingNames);
  if (existingNames.length === normalizedCount) {
    existingNames.forEach((name) => usedNames.add(name));
    return {
      ...rent,
      workerNames: existingNames,
      workerGenders: existingNames.map((name, index) => existingGenders[index] || crewGenderOfName(name))
    };
  }
  const profiles = buildRandomCrewProfiles(normalizedCount, usedNames);
  return {
    ...rent,
    workerNames: profiles.map((profile) => profile.name),
    workerGenders: profiles.map((profile) => profile.gender)
  };
};
