  const rotation = random() * Math.PI * 2;
  const baseRadius = Math.max(0.14, Math.sqrt(targetAreaSqKm / Math.PI) * (1.02 + (random() * 0.34)));
  const aspect = 0.72 + (random() * 0.92);
