const createMachineRentalOffersForMonth = (monthKey = '') => {
  const excludedNamePattern = /(견착|보행|예초기|브러시\s*커터|brush\s*cutter)/i;
  const candidates = (SHOP_ITEMS.machine || [])
    .filter((item) => {
      const type = String(item?.type || '');
      if (type === 'transport' || type === 'passenger' || type === 'mower') return false;
      if (excludedNamePattern.test(String(item?.name || ''))) return false;
      if (/(mower|brush|cutter)/i.test(String(item?.key || ''))) return false;
      return ['work', 'spray', 'aerial'].includes(type);
    })
    .filter((item) => Math.max(0, Number(item?.price) || 0) > 0);
  if (!candidates.length) return [];
  const shuffled = [...candidates];
  for (let i = shuffled.length - 1; i > 0; i -= 1) {
    const j = Math.floor(Math.random() * (i + 1));
    const temp = shuffled[i];
    shuffled[i] = shuffled[j];
    shuffled[j] = temp;
  }
  return shuffled.slice(0, Math.min(MACHINE_RENTAL_OFFER_MAX, shuffled.length)).map((item, idx) => ({
    id: `rent-${monthKey}-${idx}-${item.key}`,
    monthKey,
    itemKey: String(item.key || ''),
    dailyFee: machineRentalDailyFee(item)
  }));
};
const machineRentalDailyFee = (item) => {
  const basePrice = Math.max(0, Number(item?.price) || 0);
  const firstTier = Math.min(basePrice, 5000000);
  const secondTier = Math.min(Math.max(0, basePrice - 5000000), 10000000);
  const thirdTier = Math.max(0, basePrice - 15000000);
  const dailyFeeRaw = (
    (firstTier * 0.005)
    + (secondTier * 0.0032)
    + (thirdTier * 0.0022)
  );
  return Math.max(8000, Math.floor(dailyFeeRaw / 1000) * 1000);
};
const parkMachineInstanceAtField = (prev, instanceIdRaw, targetFieldIndex, targetSlotNo) => {
  const instanceId = String(instanceIdRaw || '');
  const safeTargetFieldIndex = Math.max(0, Math.floor(Number(targetFieldIndex) || 0));
  const safeTargetSlotNo = Math.max(1, Math.floor(Number(targetSlotNo) || 1));
  const fields = Array.isArray(prev?.fields) ? prev.fields : [];
  if (!instanceId || !fields[safeTargetFieldIndex]) return prev;
  let prevParkedFieldIndex = -1;
  let prevParkedSlotNo = 0;
  for (let fieldIdx = 0; fieldIdx < fields.length; fieldIdx += 1) {
    const field = fields[fieldIdx];
    const cap = Math.max(0, Math.min(PARKING_MAX_SLOTS, fieldTotalParkingCapacity(field)));
    const slots = Array.isArray(field?.machineParkingSlots) ? field.machineParkingSlots.slice(0, cap) : [];
    while (slots.length < cap) slots.push('');
    const slotIndex = slots.findIndex((entry) => String(entry || '') === instanceId);
    if (slotIndex < 0) continue;
    prevParkedFieldIndex = fieldIdx;
    prevParkedSlotNo = slotIndex + 1;
    break;
  }
  const movedParkingSpot = prevParkedFieldIndex >= 0
    && (prevParkedFieldIndex !== safeTargetFieldIndex || prevParkedSlotNo !== safeTargetSlotNo);
  const nextFields = fields.map((field, idx) => {
    const cap = Math.max(0, Math.min(PARKING_MAX_SLOTS, fieldTotalParkingCapacity(field)));
    const slots = Array.isArray(field?.machineParkingSlots) ? field.machineParkingSlots.slice(0, cap) : [];
    while (slots.length < cap) slots.push('');
    const prevReservedInstanceId = String(field?.evSlowChargeReservedInstanceId || '');
    const clearReservedByMove = movedParkingSpot && prevReservedInstanceId === instanceId;
    let touched = false;
    for (let i = 0; i < slots.length; i += 1) {
      if (String(slots[i] || '') !== instanceId) continue;
      slots[i] = '';
      touched = true;
    }
    if (idx === safeTargetFieldIndex) {
      const slotIdx = safeTargetSlotNo - 1;
      if (slotIdx >= 0 && slotIdx < slots.length) {
        slots[slotIdx] = instanceId;
        touched = true;
      }
    }
    if (!touched && !clearReservedByMove) return field;
    return {
      ...field,
      machineParkingSlots: slots,
      evSlowChargeReservedInstanceId: clearReservedByMove ? '' : prevReservedInstanceId
    };
  });
  return {
    ...removeVehicleFromSettlementParkingState({
      prevGame: prev,
      vehicleInstanceId: instanceId,
    }),
    fields: nextFields,
  };
};
