  for (let unitNo = removeUnitNo; unitNo < qty; unitNo += 1) {
    const fromId = machineParkingInstanceId(machineKey, unitNo + 1);
    const toId = machineParkingInstanceId(machineKey, unitNo);
    if (nextVehicleFuelStorageByInstance[fromId] === undefined) delete nextVehicleFuelStorageByInstance[toId];
    else nextVehicleFuelStorageByInstance[toId] = normalizeFuelStorageByContainer(nextVehicleFuelStorageByInstance[fromId] || {});
  }
  delete nextVehicleFuelStorageByInstance[machineParkingInstanceId(machineKey, qty)];
  const nextVehiclePlateByInstance = { ...(prev.vehiclePlateByInstance || {}) };
  for (let unitNo = removeUnitNo; unitNo < qty; unitNo += 1) {
    const fromId = machineParkingInstanceId(machineKey, unitNo + 1);
    const toId = machineParkingInstanceId(machineKey, unitNo);
    if (nextVehiclePlateByInstance[fromId] === undefined) delete nextVehiclePlateByInstance[toId];
    else nextVehiclePlateByInstance[toId] = normalizeVehiclePlateOverride(nextVehiclePlateByInstance[fromId]);
  }
  delete nextVehiclePlateByInstance[machineParkingInstanceId(machineKey, qty)];
  const nextMachinePurchaseOptionByInstance = { ...(prev.machinePurchaseOptionByInstance || {}) };
  for (let unitNo = removeUnitNo; unitNo < qty; unitNo += 1) {
    const fromId = machineParkingInstanceId(machineKey, unitNo + 1);
    const toId = machineParkingInstanceId(machineKey, unitNo);
    if (nextMachinePurchaseOptionByInstance[fromId] === undefined) delete nextMachinePurchaseOptionByInstance[toId];
    else nextMachinePurchaseOptionByInstance[toId] = String(nextMachinePurchaseOptionByInstance[fromId] || '');
  }
