const scrapBaseRateForMachineItem = (item) => {
  const type = String(item?.type || '').toLowerCase();
  const payloadKg = Math.max(0, Number(item?.payloadKg) || 0);
  if (type === 'transport') return payloadKg <= 300 ? 0.12 : 0.16;
  if (type === 'tractor') return 0.08;
  if (type === 'work' || type === 'spray') return 0.08;
  if (type === 'aerial') return 0.1;
  return payloadKg > 0 ? 0.1 : 0.08;
};
const scrapCompensationRateByDurability = (durabilityRaw) => {
  const durability = clamp(Number(durabilityRaw) || 0, 0, 100);
  return 0.35 + ((durability / 100) * 0.65);
};
const scrapCompensationAmountOfMachine = (item, durabilityRaw = 100) => {
  const basePrice = Math.max(0, Number(item?.price) || 0);
  if (basePrice <= 0) return 0;
  const amountRaw = basePrice * scrapBaseRateForMachineItem(item) * scrapCompensationRateByDurability(durabilityRaw);
  return Math.max(10000, Math.floor(amountRaw / 1000) * 1000);
};
const scrapLabelForMachineItem = (item) => {
  const type = String(item?.type || '').toLowerCase();
  const payloadKg = Math.max(0, Number(item?.payloadKg) || 0);
  if (type === 'transport') return payloadKg <= 300 ? '승용차 폐차' : '운반차 폐차';
  if (type === 'tractor') return '트랙터 폐차';
  if (type === 'work' || type === 'spray') return '농기계 폐차';
  if (type === 'aerial') return '특수장비 폐차';
  return '장비 폐차';
};
