const appleContainerAppliedUnitsByItemOfField = (field) => {
  const raw = field?.appleContainerAppliedUnitsByItemKey || {};
  const next = {};
  Object.entries(raw).forEach(([itemKeyRaw, qtyRaw]) => {
    const itemKey = String(itemKeyRaw || '');
    const qty = Math.max(0, Math.floor(Number(qtyRaw) || 0));
    if (!isAppleContainerItemKey(itemKey) || qty <= 0) return;
    next[itemKey] = qty;
  });
  return next;
};
const appleContainerAppliedUnitsOfField = (field, itemKey = '') => {
  const map = appleContainerAppliedUnitsByItemOfField(field);
  const safeKey = String(itemKey || '');
  if (safeKey) return Math.max(0, Number(map?.[safeKey]) || 0);
  return Object.values(map).reduce((sum, value) => sum + Math.max(0, Number(value) || 0), 0);
};
