const hashCodeOf = (text = '') => {
  let h = 0;
  for (let i = 0; i < text.length; i += 1) {
    h = ((h << 5) - h) + text.charCodeAt(i);
    h |= 0;
  }
  return Math.abs(h);
};
const pseudoCardNumber = (seedText = '') => {
  const seed = hashCodeOf(seedText) || 123456;
  let next = seed;
  const digits = [];
  for (let i = 0; i < 16; i += 1) {
    next = (next * 1103515245 + 12345) & 0x7fffffff;
    digits.push(String(next % 10));
  }
  const joined = digits.join('');
  return `${joined.slice(0, 4)} ${joined.slice(4, 8)} ${joined.slice(8, 12)} ${joined.slice(12, 16)}`;
};
const DEFAULT_BANK_ACCOUNT_ID = 'acct-basic-passbook';
const pseudoBankAccountNumber = (seedText = '') => {
  const seed = hashCodeOf(seedText) || 654321;
  let next = seed;
  const digits = [];
  for (let i = 0; i < 13; i += 1) {
    next = (next * 1664525 + 1013904223) & 0x7fffffff;
    digits.push(String(next % 10));
  }
  const joined = digits.join('');
  return `${joined.slice(0, 3)}-${joined.slice(3, 9)}-${joined.slice(9, 13)}`;
};
