const cardPerksFromIssued = (issuedCards = []) => {
  const next = {
    shopDiscountRate: 0,
    shopCashbackRate: 0,
    fuelDiscountRate: 0,
    fuelCashbackRate: 0,
    fuelPerLiterRebate: 0,
    saleBonusRate: 0
  };
  issuedCards.forEach((cardId) => {
    const effects = CARD_EFFECTS_BY_ID[cardId];
    if (!effects) return;
    next.shopDiscountRate = Math.max(next.shopDiscountRate, Number(effects.shopDiscountRate) || 0);
    next.shopCashbackRate = Math.max(next.shopCashbackRate, Number(effects.shopCashbackRate) || 0);
    next.fuelDiscountRate = Math.max(next.fuelDiscountRate, Number(effects.fuelDiscountRate) || 0);
    next.fuelCashbackRate = Math.max(next.fuelCashbackRate, Number(effects.fuelCashbackRate) || 0);
    next.fuelPerLiterRebate = Math.max(next.fuelPerLiterRebate, Math.max(0, Number(effects.fuelPerLiterRebate) || 0));
    next.saleBonusRate = Math.max(next.saleBonusRate, Number(effects.saleBonusRate) || 0);
  });
  return next;
};
