  const width = typeof window !== 'undefined' ? window.innerWidth : 1440;
  const height = typeof window !== 'undefined' ? window.innerHeight : 900;
  const dx = Math.max(Math.max(0, Number(x) || 0), width - Math.max(0, Number(x) || 0));
