  if (POLLINATION_STAGE_ONLY_TASK_KEYS.has(task.key)) return POLLINATION_ALLOWED_STAGES.has(growthStageLabel(field));
  if (FLOWER_THINNING_STAGE_ONLY_TASK_KEYS.has(task.key)) return FLOWER_THINNING_ALLOWED_STAGES.has(growthStageLabel(field));
  if (task.key === CANOPY_TRAINING_TASK_KEY) return true;
