    const parsed = parseMachineParkingInstanceId(instanceId);
    if (!parsed || !isSsAttachmentEligibleMachineKey(parsed.machineKey)) return;
    const qty = Math.max(0, Number(inventory?.[parsed.machineKey]) || 0);
    if (parsed.unitNo > qty) return;
    const mode = String(modeRaw || '');
    if (![SS_ATTACHMENT_MODE_SPRAYER, SS_ATTACHMENT_MODE_CARGO_BED, SS_ATTACHMENT_MODE_BARE].includes(mode)) return;
