    const baseParsed = parseMachineParkingInstanceId(baseInstanceId);
    const cargoParsed = parseMachineParkingInstanceId(cargoBedInstanceId);
    if (!baseParsed || !cargoParsed) return;
    if (!isSsAttachmentEligibleMachineKey(baseParsed.machineKey)) return;
    if (String(cargoParsed.machineKey || '') !== 'ssCargoBed') return;
    const baseQty = Math.max(0, Number(inventory?.[baseParsed.machineKey]) || 0);
    const cargoQty = Math.max(0, Number(inventory?.ssCargoBed) || 0);
    if (baseParsed.unitNo > baseQty || cargoParsed.unitNo > cargoQty) return;
    next[baseParsed.id] = cargoParsed.id;
