const addStoredFuelLitersToContainer = (fuelStorageByContainer = {}, containerKey, fuelKey, litersToAdd) => {
  const safeContainerKey = String(containerKey || '');
  const safeFuelKey = String(fuelKey || '');
  const addLiters = floorLitersToStep(litersToAdd);
  if (!safeContainerKey || !safeFuelKey || addLiters <= 0) {
    return { ...(fuelStorageByContainer || {}) };
  }
  const next = { ...(fuelStorageByContainer || {}) };
  const fuelMap = { ...(next[safeContainerKey] || {}) };
  fuelMap[safeFuelKey] = floorLitersToStep((fuelMap[safeFuelKey] || 0) + addLiters);
  next[safeContainerKey] = fuelMap;
  return next;
};
const consumeStoredFuelLitersExactFromContainer = (fuelStorageByContainer = {}, fuelKey, containerKey, litersRequested) => {
  const requested = floorLitersToStep(litersRequested);
  const safeContainerKey = String(containerKey || '');
  const safeFuelKey = String(fuelKey || '');
  if (!safeContainerKey || !safeFuelKey || requested <= 0) {
    return { nextFuelStorageByContainer: { ...(fuelStorageByContainer || {}) }, consumedLiters: 0 };
  }
  const next = { ...(fuelStorageByContainer || {}) };
  const fuelMap = { ...(next?.[safeContainerKey] || {}) };
  const hasLiters = floorLitersToStep(fuelMap?.[safeFuelKey]);
  const consumed = floorLitersToStep(Math.min(hasLiters, requested));
  if (consumed <= 0) return { nextFuelStorageByContainer: next, consumedLiters: 0 };
  const remain = floorLitersToStep(hasLiters - consumed);
  if (remain > 0) fuelMap[safeFuelKey] = remain;
  else delete fuelMap[safeFuelKey];
  if (Object.keys(fuelMap).length > 0) next[safeContainerKey] = fuelMap;
  else delete next[safeContainerKey];
  return {
    nextFuelStorageByContainer: next,
    consumedLiters: consumed
  };
};
