const isSameFuelStorageByContainer = (left = {}, right = {}) => {
  const leftKeys = Object.keys(left || {});
  const rightKeys = Object.keys(right || {});
  if (leftKeys.length !== rightKeys.length) return false;
  for (const containerKey of leftKeys) {
    if (!Object.prototype.hasOwnProperty.call(right, containerKey)) return false;
    const leftMap = left[containerKey] || {};
    const rightMap = right[containerKey] || {};
    const leftFuelKeys = Object.keys(leftMap);
    const rightFuelKeys = Object.keys(rightMap);
    if (leftFuelKeys.length !== rightFuelKeys.length) return false;
    for (const fuelKey of leftFuelKeys) {
      if (!Object.prototype.hasOwnProperty.call(rightMap, fuelKey)) return false;
      if (floorLitersToStep(leftMap[fuelKey]) !== floorLitersToStep(rightMap[fuelKey])) return false;
    }
  }
  return true;
};
