  const warehouseCenti = Object.values(game?.fuelStorageByContainer || {}).reduce((sum, fuelMap) => (
    sum + litersToCenti(fuelMap?.[fuelKey])
  ), 0);
  const parkedCarrierIds = parkedCarrierIdsOfField(game, field);
  const parkedCarrierCenti = Object.entries(game?.vehicleFuelStorageByInstance || {}).reduce((sum, [carrierIdRaw, byContainer]) => {
    const carrierId = String(carrierIdRaw || '');
    if (!parkedCarrierIds.has(carrierId)) return sum;
    const carrierSum = Object.values(byContainer || {}).reduce((inner, fuelMap) => (
      inner + litersToCenti(fuelMap?.[fuelKey])
    ), 0);
    return sum + carrierSum;
  }, 0);
  return centiToLiters(warehouseCenti + parkedCarrierCenti);
