const normalizeProfileMap = (raw, keys, fallbackValue = 0) => {
  const source = (raw && typeof raw === 'object') ? raw : {};
  return keys.reduce((acc, key) => {
    const fallback = Math.max(0, Number(fallbackValue) || 0);
    const value = Math.max(0, Number(source?.[key]));
    acc[key] = clamp(Number.isFinite(value) ? value : fallback, 0, 100);
    return acc;
  }, {});
};
const weightedProfileValue = (profile, weightMap, keys) =>
  keys.reduce((sum, key) => sum + (clamp(Number(profile?.[key]) || 0, 0, 100) * (Number(weightMap?.[key]) || 0)), 0);
const composePestGaugeValue = (pestProfile, diseaseProfile) => {
  const pestValue = weightedProfileValue(pestProfile, PEST_PROFILE_WEIGHT, PEST_PROFILE_KEYS);
  const diseaseValue = weightedProfileValue(diseaseProfile, DISEASE_PROFILE_WEIGHT, DISEASE_PROFILE_KEYS);
  return clamp((pestValue * COMPOSITE_PEST_WEIGHT.pest) + (diseaseValue * COMPOSITE_PEST_WEIGHT.disease), 0, 100);
};
const normalizePestProfile = (raw, fallbackPest = 10) => normalizeProfileMap(raw, PEST_PROFILE_KEYS, fallbackPest);
const normalizeDiseaseProfile = (raw, fallbackPest = 10) => normalizeProfileMap(raw, DISEASE_PROFILE_KEYS, fallbackPest);
const applyProfileDelta = (profile, deltaMap = {}, keys = []) => keys.reduce((acc, key) => {
  const base = clamp(Number(profile?.[key]) || 0, 0, 100);
  const delta = Number(deltaMap?.[key]) || 0;
  acc[key] = clamp(base + delta, 0, 100);
  return acc;
}, {});
const scaleProfilePairByTotalReduction = (pestProfile, diseaseProfile, totalReductionRaw) => {
  const totalReduction = Math.max(0, Number(totalReductionRaw) || 0);
  if (totalReduction <= 0) return { pestProfile, diseaseProfile };
  const totalValue = composePestGaugeValue(pestProfile, diseaseProfile);
  if (totalValue <= 0) return { pestProfile, diseaseProfile };
  const keepRatio = clamp((totalValue - totalReduction) / totalValue, 0, 1);
  return {
    pestProfile: PEST_PROFILE_KEYS.reduce((acc, key) => ({ ...acc, [key]: clamp((Number(pestProfile?.[key]) || 0) * keepRatio, 0, 100) }), {}),
    diseaseProfile: DISEASE_PROFILE_KEYS.reduce((acc, key) => ({ ...acc, [key]: clamp((Number(diseaseProfile?.[key]) || 0) * keepRatio, 0, 100) }), {})
  };
};
const pestStageBandFromLabel = (labelRaw = '') => {
  const label = String(labelRaw || '');
  if (!label) return 'default';
  if (label.includes('휴면') || label.includes('월동') || label.includes('낙엽')) return 'dormant';
  if (label.includes('발아') || label.includes('화뢰') || label.includes('풍선기')) return 'preBloom';
  if (label.includes('개화') || label.includes('수분') || label.includes('낙화')) return 'bloom';
  if (label.includes('유과') || label.includes('초기 결실') || label.includes('종자')) return 'earlyFruit';
  if (label.includes('비대') || label.includes('생리낙과') || label.includes('결실 안정')) return 'fruitGrowth';
  if (label.includes('착색') || label.includes('성숙')) return 'coloring';
  if (label.includes('수확') || label.includes('수확후')) return 'postHarvest';
  return 'default';
};
