  const subgroups = keys.map((key) => PESTICIDE_SUBGROUP_BY_KEY[key] || '');
  const hasHerbicide = subgroups.includes('herbicide');
  if (hasHerbicide && recipe.length >= 2) return '제초제(라운드업/바스타/스톰프)는 단독으로만 사용해야 합니다.';
