  if (!safeKey || need <= 0) {
    return {
      ok: true,
      nextInventory: baseInventory,
      nextSeedlingExpiryByKey: baseSeedlingExpiryByKey,
      nextVehicleCargoByInstance: baseVehicleCargoByInstance,
      consumedFromWarehouse: 0,
      consumedFromCargo: 0
    };
  }
  const warehouseStock = seedlingQtyOfBatches(baseSeedlingExpiryByKey[safeKey] || []);
  const consumeFromWarehouse = Math.min(need, warehouseStock);
  let nextSeedlingExpiryByKey = baseSeedlingExpiryByKey;
  let nextInventory = baseInventory;
  if (consumeFromWarehouse > 0) {
    const consumed = consumeSeedlingBatches(baseSeedlingExpiryByKey, safeKey, consumeFromWarehouse);
    if (consumed.consumed < consumeFromWarehouse) {
      return {
        ok: false,
        nextInventory: baseInventory,
        nextSeedlingExpiryByKey: baseSeedlingExpiryByKey,
        nextVehicleCargoByInstance: baseVehicleCargoByInstance,
        consumedFromWarehouse: 0,
        consumedFromCargo: 0
      };
    }
    nextSeedlingExpiryByKey = consumed.nextSeedlingExpiryByKey;
    nextInventory = syncSeedlingInventory({ ...baseInventory }, nextSeedlingExpiryByKey);
  }
  let remain = Math.max(0, need - consumeFromWarehouse);
  const nextVehicleCargoByInstance = { ...baseVehicleCargoByInstance };
  if (remain > 0) {
    const allowedCarrierIds = Array.from(parkedCarrierIdsOfField(gameState, field));
    for (const carrierId of allowedCarrierIds) {
      if (remain <= 0) break;
      const cargo = normalizeCargoByItemKey(nextVehicleCargoByInstance[carrierId] || {});
      const stock = Math.max(0, Math.floor(Number(cargo?.[safeKey]) || 0));
      if (stock <= 0) continue;
      const used = Math.min(remain, stock);
      remain -= used;
      const nextStock = Math.max(0, stock - used);
      if (nextStock > 0) cargo[safeKey] = nextStock;
      else delete cargo[safeKey];
      if (Object.keys(cargo).length > 0) nextVehicleCargoByInstance[carrierId] = cargo;
      else delete nextVehicleCargoByInstance[carrierId];
    }
  }
  if (remain > 0) {
    return {
      ok: false,
      nextInventory: baseInventory,
      nextSeedlingExpiryByKey: baseSeedlingExpiryByKey,
      nextVehicleCargoByInstance: baseVehicleCargoByInstance,
      consumedFromWarehouse: 0,
      consumedFromCargo: 0
    };
  }
