const trellisMaterialStatusOf = (gameState, field) => {
  const totalTrees = Math.max(0, Math.floor(fieldMaxTreeCapacity(field)));
  const installedTreesRaw = Math.max(0, fieldFacilityCountOf(field, TRELLIS_SUPPORT_FACILITY_KEY));
  const installedTrees = Math.min(totalTrees, Math.floor(installedTreesRaw));
  const remainTrees = Math.max(0, totalTrees - installedTrees);
  const stakeStock = totalItemStockWithCargoOf(gameState, TRELLIS_STAKE_ITEM_KEY, field);
  const wireStock = totalItemStockWithCargoOf(gameState, TRELLIS_WIRE_ITEM_KEY, field);
  const pipeStock = totalItemStockWithCargoOf(gameState, TRELLIS_PIPE_ITEM_KEY, field);
  const capByPipe = trellisPipeCapacityTreesByStock(installedTrees, pipeStock);
  const installableTrees = Math.max(0, Math.min(remainTrees, stakeStock, wireStock, capByPipe));
  const nextInstalledTrees = Math.min(totalTrees, installedTrees + installableTrees);
  const additionalPipeNeed = Math.max(
    0,
    Math.ceil(nextInstalledTrees / TRELLIS_PIPE_TREES_PER_UNIT) - Math.ceil(installedTrees / TRELLIS_PIPE_TREES_PER_UNIT)
  );
  return {
    totalTrees,
    installedTrees,
    remainTrees,
    stakeStock,
    wireStock,
    pipeStock,
    capByPipe,
    installableTrees,
    nextInstalledTrees,
    additionalPipeNeed
  };
};
const fieldHasIrrigationPumpInstalled = (field) => fieldHasTankOption(field, 'irrigationPump');
const fieldIrrigationPumpActive = (field) =>
  fieldHasIrrigationPumpInstalled(field) && field?.irrigationPumpEnabled !== false;
const irrigationMaxLitersPerTreeByFacilityAndPump = (facilityKey, pumpActive = false) => {
  const safeKey = String(facilityKey || '');
  if (safeKey === 'dripIrrigation') return pumpActive ? DRIP_PUMP_MAX_L_PER_TREE : DRIP_BASE_MAX_L_PER_TREE;
  if (safeKey === 'sprinklerIrrigation') return pumpActive ? SPRINKLER_PUMP_MAX_L_PER_TREE : SPRINKLER_BASE_MAX_L_PER_TREE;
  return IRRIGATION_MAX_L_PER_TREE;
};
const irrigationInstallStatusOf = (gameState, field, taskKey) => {
  const liveTrees = Math.max(0, Math.floor(liveTreeCount(field)));
  const trellisInstalledTrees = Math.max(0, Math.floor(fieldFacilityCountOf(field, TRELLIS_SUPPORT_FACILITY_KEY)));
  const totalTrees = Math.max(liveTrees, trellisInstalledTrees);
  const pipeInstalled = Math.min(totalTrees, Math.max(0, Math.floor(fieldFacilityCountOf(field, IRRIGATION_PIPE_FACILITY_KEY))));
  const dripInstalled = Math.min(totalTrees, Math.max(0, Math.floor(fieldFacilityCountOf(field, 'dripIrrigation'))));
  const sprinklerInstalled = Math.min(totalTrees, Math.max(0, Math.floor(fieldFacilityCountOf(field, 'sprinklerIrrigation'))));
  const microInstalled = Math.min(totalTrees, Math.max(0, Math.floor(fieldFacilityCountOf(field, MICRO_SPRINKLER_IRRIGATION_FACILITY_KEY))));
  const pipeRollStock = totalItemStockWithCargoOf(gameState, IRRIGATION_PIPE_ITEM_KEY, field);
  const dripNozzleStock = totalItemStockWithCargoOf(gameState, DRIP_NOZZLE_ITEM_KEY, field);
  const sprinklerNozzleStock = totalItemStockWithCargoOf(gameState, SPRINKLER_NOZZLE_ITEM_KEY, field);
  const microNozzleStock = totalItemStockWithCargoOf(gameState, MICRO_NOZZLE_ITEM_KEY, field);
  const pipeInstallableByStock = Math.max(0, Math.min(totalTrees - pipeInstalled, pipeRollStock * IRRIGATION_PIPE_METERS_PER_ROLL));
  const dripInstallableByStock = Math.max(0, Math.min(totalTrees - dripInstalled, dripNozzleStock));
  const sprinklerInstallableByStock = Math.max(0, Math.min(totalTrees - sprinklerInstalled, sprinklerNozzleStock));
  const microInstallableByStock = Math.max(0, Math.min(totalTrees - microInstalled, microNozzleStock));
  if (taskKey === IRRIGATION_PIPE_INSTALL_TASK_KEY) {
    return {
      totalTrees,
      installedTrees: pipeInstalled,
      remainTrees: Math.max(0, totalTrees - pipeInstalled),
      installableTrees: pipeInstallableByStock,
      nextInstalledTrees: Math.min(totalTrees, pipeInstalled + pipeInstallableByStock),
      itemKey: IRRIGATION_PIPE_ITEM_KEY,
      itemStock: pipeRollStock
    };
  }
  if (taskKey === DRIP_NOZZLE_INSTALL_TASK_KEY) {
    const remainByPipe = Math.max(0, pipeInstalled - dripInstalled);
    const installableTrees = Math.max(0, Math.min(remainByPipe, dripInstallableByStock));
    return {
      totalTrees,
      installedTrees: dripInstalled,
      remainTrees: Math.max(0, totalTrees - dripInstalled),
      installableTrees,
      nextInstalledTrees: Math.min(totalTrees, dripInstalled + installableTrees),
      itemKey: DRIP_NOZZLE_ITEM_KEY,
      itemStock: dripNozzleStock,
      prerequisiteCount: pipeInstalled
    };
  }
  if (taskKey === SPRINKLER_NOZZLE_INSTALL_TASK_KEY) {
    const remainByDrip = Math.max(0, dripInstalled - sprinklerInstalled);
    const installableTrees = Math.max(0, Math.min(remainByDrip, sprinklerInstallableByStock));
    return {
      totalTrees,
      installedTrees: sprinklerInstalled,
      remainTrees: Math.max(0, totalTrees - sprinklerInstalled),
      installableTrees,
      nextInstalledTrees: Math.min(totalTrees, sprinklerInstalled + installableTrees),
      itemKey: SPRINKLER_NOZZLE_ITEM_KEY,
      itemStock: sprinklerNozzleStock,
      prerequisiteCount: dripInstalled
    };
  }
  if (taskKey === MICRO_NOZZLE_INSTALL_TASK_KEY) {
    const remainByDrip = Math.max(0, dripInstalled - microInstalled);
    const installableTrees = Math.max(0, Math.min(remainByDrip, microInstallableByStock));
    return {
      totalTrees,
      installedTrees: microInstalled,
      remainTrees: Math.max(0, totalTrees - microInstalled),
      installableTrees,
      nextInstalledTrees: Math.min(totalTrees, microInstalled + installableTrees),
      itemKey: MICRO_NOZZLE_ITEM_KEY,
      itemStock: microNozzleStock,
      prerequisiteCount: dripInstalled
    };
  }
  return {
    totalTrees: 0,
    installedTrees: 0,
    remainTrees: 0,
    installableTrees: 0,
    nextInstalledTrees: 0,
    itemKey: '',
    itemStock: 0
  };
};
