const splitLoadsByCapacity = (loads = [], maxKg = 0) => {
  let remain = Math.max(0, Number(maxKg) || 0);
  const moved = [];
  const left = [];
  (loads || []).forEach((load) => {
    const qty = Math.max(0, Number(load?.qty) || 0);
    if (qty <= 0) return;
    if (remain <= 0) {
      left.push({ ...load });
      return;
    }
    if (qty <= remain) {
      moved.push({ ...load });
      remain -= qty;
      return;
    }
    moved.push({ ...load, qty: remain });
    left.push({ ...load, qty: qty - remain });
    remain = 0;
  });
  return { moved, left };
};
