const installedFacilityKeysOf = (field) => {
  const keysFromFlags = Object.entries(field?.landFacilities || {})
    .filter(([, enabled]) => Boolean(enabled))
    .map(([key]) => key);
  const keysFromCounts = Object.entries(field?.landFacilityCounts || {})
    .filter(([, count]) => (Number(count) || 0) > 0)
    .map(([key]) => key);
  return Array.from(new Set([...keysFromFlags, ...keysFromCounts]));
};
const facilityDurabilityRuleOf = (facilityKey) =>
  FACILITY_DURABILITY_RULES[facilityKey] || FACILITY_DURABILITY_DEFAULT_RULE;
const fieldFacilityDurabilityOf = (field, facilityKey) => {
  if (fieldFacilityCountOf(field, facilityKey) <= 0) return 0;
  const rawMap = field?.facilityDurabilityByKey || field?.tankDurabilityByFacility || {};
  return clamp(Number(rawMap?.[facilityKey] ?? 100), 0, 100);
};
const fieldFacilityRepairStateOf = (field, facilityKey) => field?.facilityRepairByKey?.[facilityKey] || null;
const fieldFacilityUnderRepair = (field, facilityKey, day) => {
  const repair = fieldFacilityRepairStateOf(field, facilityKey);
  if (!repair) return false;
  return Number(repair.readyDay) > Number(day || 0);
};
const normalizeFacilityConstructionOrder = (order, fallbackDay = 1) => {
  const fieldId = String(order?.fieldId || '').trim();
  const facilityKey = String(order?.facilityKey || '').trim();
  if (!fieldId || !facilityKey || !FACILITY_MAP[facilityKey]) return null;
  const startDay = Math.max(1, Math.floor(Number(order?.startDay) || fallbackDay || 1));
  const buildDays = Math.max(1, Math.floor(Number(order?.buildDays) || facilityInstallDaysOf(facilityKey)));
  const readyDay = Math.max(startDay + 1, Math.floor(Number(order?.readyDay) || (startDay + buildDays)));
  const treeInstallCount = Math.max(0, Math.floor(Number(order?.treeInstallCount) || 0));
  const occupiedPy = Math.max(0, Number(order?.occupiedPy) || 0);
  return {
    id: String(order?.id || `facility-build:${facilityKey}:${fieldId}:${startDay}:${readyDay}`),
    fieldId,
    fieldName: String(order?.fieldName || '').trim(),
    facilityKey,
    facilityName: String(order?.facilityName || FACILITY_MAP[facilityKey]?.name || facilityKey),
    startDay,
    readyDay,
    buildDays,
    cost: Math.max(0, Number(order?.cost) || 0),
    occupiedPy,
    optionSuffix: String(order?.optionSuffix || ''),
    treeInstallCount,
    tankUpgradeOptionKeys: Array.isArray(order?.tankUpgradeOptionKeys) ? Array.from(new Set(order.tankUpgradeOptionKeys.map((key) => String(key || '').trim()).filter(Boolean))) : [],
    housingOptionKeys: Array.isArray(order?.housingOptionKeys) ? Array.from(new Set(order.housingOptionKeys.map((key) => String(key || '').trim()).filter(Boolean))) : [],
    wellDepthOptionKey: String(order?.wellDepthOptionKey || ''),
    wellPrecisionSensorEnabled: Boolean(order?.wellPrecisionSensorEnabled),
    installRequest: order?.installRequest && typeof order.installRequest === 'object'
      ? { ...order.installRequest }
      : {}
  };
};
const facilityConstructionOrdersOfField = (gameState, fieldId) => {
  const normalizedFieldId = String(fieldId || '').trim();
  if (!normalizedFieldId) return [];
  return (Array.isArray(gameState?.facilityConstructionOrders) ? gameState.facilityConstructionOrders : [])
    .filter((order) => String(order?.fieldId || '').trim() === normalizedFieldId);
};
const fieldFacilityUnderConstruction = (gameState, fieldId, facilityKey) => (
  facilityConstructionOrdersOfField(gameState, fieldId)
    .some((order) => String(order?.facilityKey || '').trim() === String(facilityKey || '').trim())
);
const fieldReservedPyByPendingConstruction = (gameState, field) => (
  facilityConstructionOrdersOfField(gameState, field?.id)
    .reduce((sum, order) => sum + Math.max(0, Number(order?.occupiedPy) || 0), 0)
);
const fieldFacilityUsable = (field, facilityKey, day) =>
  fieldFacilityCountOf(field, facilityKey) > 0
  && !fieldFacilityUnderRepair(field, facilityKey, day)
  && fieldFacilityDurabilityOf(field, facilityKey) > 0;
const housingInstalledWaterTankCapacityLitersOfField = (field, durabilityRaw = {}) => {
  if (!field) return 0;
  const installedByFacility = field?.housingWaterTankInstallationsByFacilityKey || {};
  return Object.entries(installedByFacility).reduce((sum, [facilityKeyRaw, slotMapRaw]) => {
    return sum + housingInstalledWaterTankCapacityLitersOfFacility(field, facilityKeyRaw, durabilityRaw, slotMapRaw);
  }, 0);
};
const housingInstalledWaterTankCapacityLitersOfFacility = (field, facilityKeyRaw = '', durabilityRaw = {}, slotMapRaw = null) => {
  if (!field) return 0;
  const fieldId = String(field?.id || '');
  const facilityKey = String(facilityKeyRaw || '');
  if (!fieldId || !facilityKey) return 0;
  const installedByFacility = field?.housingWaterTankInstallationsByFacilityKey || {};
  const slotMap = normalizeHousingWaterTankInstallations(
    slotMapRaw || installedByFacility?.[facilityKey] || {},
    facilityKey
  );
  return Object.entries(slotMap).reduce((slotSum, [slotKeyRaw, itemKeyRaw]) => {
    const slotKey = String(slotKeyRaw || '');
    const durability = housingInstalledSlotDurabilityOf(
      { housingInstalledDurabilityByFieldFacility: durabilityRaw },
      fieldId,
      facilityKey,
      'waterTank',
      slotKey
    );
    if (durability !== null && durability <= 0) return slotSum;
    const itemKey = String(itemKeyRaw || '');
    const liters = Math.max(0, Number(SHOP_ITEM_META_BY_KEY?.[itemKey]?.waterTankLiters) || 0);
    return slotSum + liters;
  }, 0);
};
const fieldTankOperationalCapacityLiters = (field, day) =>
  TANK_FACILITY_KEYS.reduce((sum, key) => (
    sum + (fieldFacilityUsable(field, key, day) ? (fieldFacilityCountOf(field, key) * (TANK_CAPACITY_LITERS[key] || 0)) : 0)
  ), 0);
const fieldLivingWaterTankOperationalCapacityLiters = (field, day, housingInstalledDurabilityRaw = {}) =>
  fieldTankOperationalCapacityLiters(field, day) + housingInstalledWaterTankCapacityLitersOfField(field, housingInstalledDurabilityRaw);
const housingWaterReserveInfoOfField = (field, day, housingInstalledDurabilityRaw = {}, facilityKeyRaw = '') => {
  const externalCapacityLiters = fieldTankOperationalCapacityLiters(field, day);
  const facilityKey = String(facilityKeyRaw || '');
  const internalCapacityLiters = facilityKey
    ? housingInstalledWaterTankCapacityLitersOfFacility(field, facilityKey, housingInstalledDurabilityRaw)
    : housingInstalledWaterTankCapacityLitersOfField(field, housingInstalledDurabilityRaw);
  const totalCapacityLiters = externalCapacityLiters + internalCapacityLiters;
  const totalAvailableLiters = clamp(
    fieldTankWaterLitersEffective(field),
    0,
    Math.max(totalCapacityLiters, fieldTankWaterLitersEffective(field))
  );
  const internalAvailableLiters = internalCapacityLiters > 0
    ? Math.min(internalCapacityLiters, totalAvailableLiters)
    : 0;
  const externalAvailableLiters = externalCapacityLiters > 0
    ? (internalCapacityLiters > 0
        ? clamp(totalAvailableLiters - internalCapacityLiters, 0, externalCapacityLiters)
        : Math.min(externalCapacityLiters, totalAvailableLiters))
    : 0;
  const activeAvailableLiters = internalCapacityLiters > 0 ? internalAvailableLiters : externalAvailableLiters;
  const activeCapacityLiters = internalCapacityLiters > 0 ? internalCapacityLiters : externalCapacityLiters;
  return {
    externalCapacityLiters,
    externalAvailableLiters,
    internalCapacityLiters,
    internalAvailableLiters,
    activeCapacityLiters,
    activeAvailableLiters,
    totalCapacityLiters,
    totalAvailableLiters,
    hasExternalTank: externalCapacityLiters > 0,
    hasInternalTank: internalCapacityLiters > 0,
    hasActiveWaterSource: activeCapacityLiters > 0 && activeAvailableLiters > 0
  };
};
const applyFacilityDurabilityWear = (baseMap, facilityKey, wearAmount) => {
  const current = clamp(Number(baseMap?.[facilityKey] ?? 100), 0, 100);
  return {
    ...(baseMap || {}),
    [facilityKey]: clamp(current - Math.max(0, Number(wearAmount) || 0), 0, 100)
  };
};
const fieldTankDurabilityOf = (field, facilityKey) => {
  return fieldFacilityDurabilityOf(field, facilityKey);
};
const fieldTankDurabilityAvg = (field) => {
  const installed = TANK_FACILITY_KEYS
    .map((key) => ({ key, count: fieldFacilityCountOf(field, key) }))
    .filter((x) => x.count > 0);
  if (!installed.length) return 0;
  const totalCount = installed.reduce((sum, x) => sum + x.count, 0);
  if (totalCount <= 0) return 0;
  const weighted = installed.reduce((sum, x) => sum + (fieldTankDurabilityOf(field, x.key) * x.count), 0);
  return clamp(weighted / totalCount, 0, 100);
};
const tankGaugeSegmentText = (tankWaterLiters, tankCapacityLiters) => {
  if (tankCapacityLiters <= 0) return '0/3';
  const ratio = clamp((Number(tankWaterLiters) || 0) / tankCapacityLiters, 0, 1);
  if (ratio <= 0) return '0/3';
  if (ratio <= (1 / 3)) return '1/3';
  if (ratio <= (2 / 3)) return '2/3';
  return '3/3';
};
const tankWaterDisplayText = (field, tankWaterLiters, tankCapacityLiters) => {
  if (tankCapacityLiters <= 0) return '0L / 0L';
  if (fieldHasTankOption(field, 'waterLevelGauge')) {
    return `${Math.floor(tankWaterLiters).toLocaleString()}L / ${tankCapacityLiters.toLocaleString()}L`;
  }
  return `대략 ${tankGaugeSegmentText(tankWaterLiters, tankCapacityLiters)}`;
};
const tankWaterDisplayTextByGaugeEnabled = (tankWaterLiters, tankCapacityLiters, hasWaterLevelGauge) => {
  if (tankCapacityLiters <= 0) return '0L / 0L';
  if (!hasWaterLevelGauge) return `대략 ${tankGaugeSegmentText(tankWaterLiters, tankCapacityLiters)}`;
  return `${Math.floor(tankWaterLiters).toLocaleString()}L / ${tankCapacityLiters.toLocaleString()}L`;
};
const splitTankWaterByFacility = (field, totalWaterLiters) => {
  const next = {};
  const units = splitTankWaterByUnit(field, totalWaterLiters);
  units.forEach((unit) => {
    next[unit.facilityKey] = (Number(next[unit.facilityKey]) || 0) + (Number(unit.water) || 0);
  });
  return next;
};
const splitTankWaterByUnit = (field, totalWaterLiters) => {
  const units = [];
  TANK_FACILITY_KEYS.forEach((facilityKey) => {
    const count = Math.max(0, fieldFacilityCountOf(field, facilityKey));
    const unitCapacity = Math.max(0, Number(TANK_CAPACITY_LITERS[facilityKey]) || 0);
    if (count <= 0 || unitCapacity <= 0) return;
    for (let i = 0; i < count; i += 1) {
      units.push({
        unitId: `${facilityKey}-${i + 1}`,
        facilityKey,
        index: i + 1,
        capacity: unitCapacity,
        water: 0
      });
    }
  });
  if (!units.length) return units;
  const rawMap = field?.tankWaterLitersByUnit || {};
  const tankMap = {};
  units.forEach((unit) => {
    tankMap[unit.unitId] = clamp(Number(rawMap?.[unit.unitId]) || 0, 0, unit.capacity);
  });
  let mapTotal = Object.values(tankMap).reduce((sum, value) => sum + value, 0);
  const targetTotal = clamp(Number(totalWaterLiters) || 0, 0, units.reduce((sum, unit) => sum + unit.capacity, 0));
  if (mapTotal < targetTotal) {
    let add = targetTotal - mapTotal;
    for (const unit of units) {
      if (add <= 0) break;
      const room = Math.max(0, unit.capacity - tankMap[unit.unitId]);
      if (room <= 0) continue;
      const fill = Math.min(room, add);
      tankMap[unit.unitId] += fill;
      add -= fill;
    }
  } else if (mapTotal > targetTotal) {
    let remove = mapTotal - targetTotal;
    for (let i = units.length - 1; i >= 0; i -= 1) {
      if (remove <= 0) break;
      const unit = units[i];
      const have = Math.max(0, tankMap[unit.unitId]);
      if (have <= 0) continue;
      const take = Math.min(have, remove);
      tankMap[unit.unitId] -= take;
      remove -= take;
    }
  }
  return units.map((unit) => ({
    ...unit,
    water: clamp(Number(tankMap[unit.unitId]) || 0, 0, unit.capacity)
  }));
};
const tankUnitWaterMapFromUnits = (units = []) =>
  (units || []).reduce((acc, unit) => {
    const liters = Math.max(0, Number(unit?.water) || 0);
    if (liters > 0) acc[unit.unitId] = liters;
    return acc;
  }, {});
const fieldTankWaterLitersEffective = (field) => {
  const direct = Math.max(0, Number(field?.tankWaterLiters) || 0);
  const byUnit = Object.values(field?.tankWaterLitersByUnit || {}).reduce(
    (sum, liters) => sum + Math.max(0, Number(liters) || 0),
    0
  );
  return Math.max(direct, byUnit);
};
const HOUSING_LIVING_WATER_SOURCE_QUALITY = 85;
const HOUSING_MUNICIPAL_WATER_QUALITY = 95;
const HOUSING_MUNICIPAL_WATERWORKS_MIN_COST = 5000000;
const HOUSING_MUNICIPAL_WATERWORKS_MAX_COST = 15000000;
const HOUSING_MUNICIPAL_WATERWORKS_DISTANCE_CAP_KM = 1.5;
const HOUSING_MUNICIPAL_WATERWORKS_COST_STEP = 100000;
const HOUSING_MUNICIPAL_WATERWORKS_BUILD_DAYS = 3;
const HOUSING_LIVING_WATER_STORED_MIN_QUALITY = 55;
const HOUSING_LIVING_WATER_DAILY_DECAY = 3;
const normalizeHousingLivingWaterQuality = (valueRaw = 0) => clamp(Number(valueRaw) || 0, 0, 100);
const housingLivingWaterQualityLabelOf = (qualityRaw = 0) => {
  const quality = normalizeHousingLivingWaterQuality(qualityRaw);
  if (quality >= 80) return '좋음';
  if (quality >= 65) return '보통';
  if (quality >= 55) return '저하';
  return '관리 불가';
};
const distanceKmFromPointToMapSegment = (p, a, b) => {
  const px = Number(p?.x);
  const py = Number(p?.y);
  const ax = Number(a?.x);
  const ay = Number(a?.y);
  const bx = Number(b?.x);
  const by = Number(b?.y);
  if (![px, py, ax, ay, bx, by].every(Number.isFinite)) return Infinity;
  const dx = bx - ax;
  const dy = by - ay;
  const lenSq = (dx * dx) + (dy * dy);
  if (lenSq <= 0) return Math.hypot(px - ax, py - ay);
  const t = clamp((((px - ax) * dx) + ((py - ay) * dy)) / lenSq, 0, 1);
  return Math.hypot(px - (ax + (dx * t)), py - (ay + (dy * t)));
};
const nearestRoadDistanceKmFromPoint = (point, roads = []) => {
  if (!point || !Array.isArray(roads)) return Infinity;
  return roads.reduce((minDistance, road) => {
    const points = Array.isArray(road?.points) ? road.points : [];
    if (points.length < 2) return minDistance;
    let nextMin = minDistance;
    for (let i = 1; i < points.length; i += 1) {
      nextMin = Math.min(nextMin, distanceKmFromPointToMapSegment(point, points[i - 1], points[i]));
    }
    return nextMin;
  }, Infinity);
};
const housingMunicipalWaterworksQuoteOf = ({ field = null, fieldPoint = null, roads = [] } = {}) => {
  const roadDistanceKm = nearestRoadDistanceKmFromPoint(fieldPoint, roads);
  const safeDistanceKm = Number.isFinite(roadDistanceKm)
    ? Math.max(0, roadDistanceKm)
    : HOUSING_MUNICIPAL_WATERWORKS_DISTANCE_CAP_KM * 0.5;
  const distanceRatio = clamp(safeDistanceKm / HOUSING_MUNICIPAL_WATERWORKS_DISTANCE_CAP_KM, 0, 1);
  const rawCost = HOUSING_MUNICIPAL_WATERWORKS_MIN_COST
    + ((HOUSING_MUNICIPAL_WATERWORKS_MAX_COST - HOUSING_MUNICIPAL_WATERWORKS_MIN_COST) * distanceRatio);
  const roundedCost = Math.round(rawCost / HOUSING_MUNICIPAL_WATERWORKS_COST_STEP)
    * HOUSING_MUNICIPAL_WATERWORKS_COST_STEP;
  return {
    cost: clamp(roundedCost, HOUSING_MUNICIPAL_WATERWORKS_MIN_COST, HOUSING_MUNICIPAL_WATERWORKS_MAX_COST),
    roadDistanceKm: safeDistanceKm,
    hasRoadDistance: Number.isFinite(roadDistanceKm),
    fieldName: String(field?.name || '')
  };
};
const blendHousingLivingWaterQualityWithWellWater = ({ field, addLiters }) => {
  const incomingLiters = Math.max(0, Number(addLiters) || 0);
  if (!field || incomingLiters <= 0) return normalizeHousingLivingWaterQuality(field?.housingLivingWaterQuality);
  const beforeLiters = fieldTankWaterLitersEffective(field);
  const beforeQuality = beforeLiters > 0
    ? Math.max(
        HOUSING_LIVING_WATER_STORED_MIN_QUALITY,
        normalizeHousingLivingWaterQuality(field?.housingLivingWaterQuality || HOUSING_LIVING_WATER_STORED_MIN_QUALITY)
      )
    : HOUSING_LIVING_WATER_SOURCE_QUALITY;
  const blended = ((beforeQuality * beforeLiters) + (HOUSING_LIVING_WATER_SOURCE_QUALITY * incomingLiters))
    / Math.max(1, beforeLiters + incomingLiters);
  return clamp(blended, HOUSING_LIVING_WATER_STORED_MIN_QUALITY, HOUSING_LIVING_WATER_SOURCE_QUALITY);
};
const decayHousingLivingWaterQualityForField = (field, day, housingInstalledDurabilityRaw = {}) => {
  if (!field) return field;
  if (field?.housingMunicipalWaterConnected) {
    return {
      ...field,
      housingLivingWaterQuality: HOUSING_MUNICIPAL_WATER_QUALITY
    };
  }
  const waterReserve = housingWaterReserveInfoOfField(field, day, housingInstalledDurabilityRaw);
  if (waterReserve.activeCapacityLiters <= 0 || waterReserve.activeAvailableLiters <= 0) {
    return {
      ...field,
      housingLivingWaterQuality: 0
    };
  }
  const current = normalizeHousingLivingWaterQuality(
    field?.housingLivingWaterQuality || HOUSING_LIVING_WATER_STORED_MIN_QUALITY
  );
  return {
    ...field,
    housingLivingWaterQuality: Math.max(
      HOUSING_LIVING_WATER_STORED_MIN_QUALITY,
      current - HOUSING_LIVING_WATER_DAILY_DECAY
    )
  };
};
const consumeHousingDailyWaterForField = ({ field, day, fieldIndex, housingInstalledDurabilityByFieldFacility = {} }) => {
  if (!field) return { field, logs: [] };
  if (field?.housingMunicipalWaterConnected) {
    return {
      field: {
        ...field,
        housingLivingWaterQuality: HOUSING_MUNICIPAL_WATER_QUALITY
      },
      logs: []
    };
  }
  const hasUsableHousing = HOUSING_FACILITY_KEYS.some((facilityKey) => fieldFacilityUsable(field, facilityKey, day));
  if (!hasUsableHousing) return { field, logs: [] };
  const requiredLiters = Math.max(0, Number(HOUSING_DAILY_LIVING_WATER_LITERS) || 0);
  if (requiredLiters <= 0) return { field, logs: [] };
  const waterReserve = housingWaterReserveInfoOfField(field, day, housingInstalledDurabilityByFieldFacility);
  const capacityLiters = waterReserve.activeCapacityLiters;
  const currentLiters = waterReserve.activeAvailableLiters;
  const totalCurrentLiters = waterReserve.totalAvailableLiters;
  const label = `밭 ${Number(fieldIndex) + 1}`;
  if (capacityLiters <= 0) {
    return {
      field,
      logs: [`${label} 하우징 생활용수 부족: 사용할 물탱크가 없습니다.`]
    };
  }
  if (currentLiters + 0.0001 < requiredLiters) {
    const nextUnits = splitTankWaterByUnit(field, 0);
    return {
      field: {
        ...field,
        tankWaterLiters: 0,
        tankWaterLitersByUnit: tankUnitWaterMapFromUnits(nextUnits),
        housingLivingWaterQuality: 0
      },
      logs: [`${label} 하우징 생활용수 부족: 물탱크 물 ${Math.floor(currentLiters).toLocaleString()}L만 사용했습니다.`]
    };
  }
  const nextLiters = Math.max(0, totalCurrentLiters - requiredLiters);
  const nextUnits = splitTankWaterByUnit(field, nextLiters);
  return {
    field: {
      ...field,
      tankWaterLiters: nextLiters,
      tankWaterLitersByUnit: tankUnitWaterMapFromUnits(nextUnits),
      ...(nextLiters <= 0 ? { housingLivingWaterQuality: 0 } : {})
    },
    logs: []
  };
};
