  if (/약한우박|우박/.test(weatherName)) return { label: '우박 가능', isPrecip: true };
  if (/대설|폭설/.test(weatherName)) return { label: '강설 강함', isPrecip: true };
  if (/눈|진눈깨비/.test(weatherName)) return { label: '강설 가능', isPrecip: true };
