  if (/황사/.test(weatherName)) return '황사';
  if (/눈|대설|폭설|진눈깨비/.test(weatherName)) return '눈';
  if (/비|소나기|장마|폭우|이슬비|우박|봄비|가을비/.test(weatherName)) return '비';
  return '';
