const TREE_IMAGE_SRC_BY_KEYWORD_SIGNATURE = new Map();
const findTreeImageSrcByKeywords = (keywords = [], { preferWeatherVariant = false, preferNightVariant = false } = {}) => {
  const normalizedKeywords = keywords
    .map((keyword) => normalizeAssetKey(keyword))
    .filter(Boolean);
  if (!normalizedKeywords.length) return '';
  const cacheKey = `${normalizedKeywords.join('|')}::weather=${preferWeatherVariant ? '1' : '0'}::night=${preferNightVariant ? '1' : '0'}`;
  if (TREE_IMAGE_SRC_BY_KEYWORD_SIGNATURE.has(cacheKey)) {
    return TREE_IMAGE_SRC_BY_KEYWORD_SIGNATURE.get(cacheKey);
  }
  const matched = TREE_IMAGE_ENTRIES.filter(({ normalizedPath }) =>
    normalizedKeywords.every((keyword) => normalizedPath.includes(keyword))
  );
  if (!matched.length) {
    TREE_IMAGE_SRC_BY_KEYWORD_SIGNATURE.set(cacheKey, '');
    return '';
  }
  const ordered = [...matched].sort((a, b) => {
    const nightRank = Number(Boolean(b.isNightVariant)) - Number(Boolean(a.isNightVariant));
    if (preferNightVariant && nightRank !== 0) return nightRank;
    const weatherRank = Number(Boolean(b.isWeatherVariant)) - Number(Boolean(a.isWeatherVariant));
    if (weatherRank !== 0) return preferWeatherVariant ? weatherRank : -weatherRank;
    return a.path.length - b.path.length;
  });
  const resolvedSrc = ordered[0]?.src || '';
  TREE_IMAGE_SRC_BY_KEYWORD_SIGNATURE.set(cacheKey, resolvedSrc);
  return resolvedSrc;
};
const dominantPlantedAgeYearOfField = (field, day) => {
  const rows = cropRowsByVarietyAndAge(field, day, CROPS).filter((row) => (Number(row?.trees) || 0) > 0);
  if (!rows.length) return Math.max(1, treeAgeYear(field, day));
  const winner = rows.reduce((best, row) => {
    if (!best) return row;
    const bestTrees = Number(best?.trees) || 0;
    const rowTrees = Number(row?.trees) || 0;
    if (rowTrees !== bestTrees) return rowTrees > bestTrees ? row : best;
    const bestAge = Math.max(1, Math.floor(Number(best?.ageYear) || 1));
    const rowAge = Math.max(1, Math.floor(Number(row?.ageYear) || 1));
    return rowAge > bestAge ? row : best;
  }, null);
  return Math.max(1, Math.floor(Number(winner?.ageYear) || 1));
};
const pickFieldPanelTreeImage = ({ field, day, month, weatherName, isNight = false }) => {
  if (!field?.cropId) return '';
  const ageYear = dominantPlantedAgeYearOfField(field, day);
  const ageToken = ageYear >= 3 ? '3년생' : `${ageYear}년생`;
  const seasonToken = TREE_SEASON_KO_BY_KEY[seasonKey(month)] || '';
  const weatherToken = treeWeatherAssetTokenOf(weatherName);
  const candidateQueries = [];
  if (ageYear >= 3) {
    const stageToken = treeStageAssetKeywordOf(field?.growth);
    if (weatherToken) {
      candidateQueries.push({
        keywords: [ageToken, stageToken, weatherToken],
        options: { preferWeatherVariant: true }
      });
    }
    candidateQueries.push({ keywords: [ageToken, stageToken], options: {} });
  }
  if (weatherToken) {
    candidateQueries.push({
      keywords: [ageToken, seasonToken, weatherToken],
      options: { preferWeatherVariant: true }
    });
  }
  candidateQueries.push({ keywords: [ageToken, seasonToken], options: {} });
  candidateQueries.push({ keywords: [ageToken], options: {} });

  if (isNight) {
    for (const query of candidateQueries) {
      const strictNight = findTreeImageSrcByKeywords(
        [...query.keywords, '밤'],
        { ...query.options, preferNightVariant: true }
      );
      if (strictNight) return strictNight;
      const preferredNight = findTreeImageSrcByKeywords(
        query.keywords,
        { ...query.options, preferNightVariant: true }
      );
      const preferredNightEntry = TREE_IMAGE_ENTRIES.find((entry) => entry.src === preferredNight);
      if (preferredNightEntry?.isNightVariant) return preferredNight;
    }
  }

  for (const query of candidateQueries) {
    const picked = findTreeImageSrcByKeywords(
      query.keywords,
      { ...query.options, preferNightVariant: isNight }
    );
    if (picked) return picked;
  }
  return '';
};
