const startingVehicleDiscountedCostOf = (machineKeyRaw = '') => {
  const machineKey = String(machineKeyRaw || '').trim();
  if (!machineKey) return 0;
  const item = MACHINE_ITEM_MAP?.[machineKey] || EQUIPMENT_ITEM_MAP?.[machineKey] || null;
  const basePrice = Math.max(0, Number(item?.price) || 0);
  return Math.max(0, Math.round(basePrice * (1 - STARTING_VEHICLE_DISCOUNT_RATE)));
};
const buildStartingVehicleSetup = (startingVehicleKey = 'none') => {
  const selectedOption = STARTING_VEHICLE_SETUP_OPTIONS[startingVehicleKey] || STARTING_VEHICLE_SETUP_OPTIONS.none;
  const item = MACHINE_ITEM_MAP?.[selectedOption?.machineKey] || EQUIPMENT_ITEM_MAP?.[selectedOption?.machineKey] || null;
  if (!item) return null;
  const instanceId = machineParkingInstanceId(item.key, 1);
  const driveFuelCapacity = Math.max(0, Number(item?.driveFuelTankLiters) || Number(item?.fuelTankLiters) || 0);
  return {
    option: selectedOption,
    item,
    instanceId,
    discountedCost: startingVehicleDiscountedCostOf(selectedOption?.machineKey),
    driveFuelCapacity,
    parkingSlots: [instanceId]
  };
};
