const slotKey = (slot) => SAVE_SLOTS[clamp(Number(slot) || 0, 0, SAVE_SLOTS.length - 1)];
let remoteSaveSyncHandler = null;
let runtimeSaveSlotsByKey = {};
const setRemoteSaveSyncHandler = (handler) => {
  remoteSaveSyncHandler = typeof handler === 'function' ? handler : null;
};
const cloneSaveSlotPayload = (payload) => {
  if (!payload || !Array.isArray(payload.fields)) return null;
  try {
    return JSON.parse(JSON.stringify(payload));
  } catch {
    return null;
  }
};
const replaceLocalSaveSlots = (slotsByKey = {}) => {
  const nextSlots = {};
  SAVE_SLOTS.forEach((_, slot) => {
    const key = slotKey(slot);
    const payload = cloneSaveSlotPayload(slotsByKey?.[key]);
    if (payload) nextSlots[key] = payload;
  });
  runtimeSaveSlotsByKey = nextSlots;
};
const clearLocalSaveSlot = (slot) => {
  const key = slotKey(slot);
  if (!key) return;
  delete runtimeSaveSlotsByKey[key];
};
const clearLocalSaveSlots = () => replaceLocalSaveSlots({});
const saveGame = (game, slot) => {
  const key = slotKey(slot);
  const payload = cloneSaveSlotPayload(game);
  if (!payload) throw new Error('save_slot_serialize_failed');
  runtimeSaveSlotsByKey = {
    ...runtimeSaveSlotsByKey,
    [key]: payload,
  };
  remoteSaveSyncHandler?.(slot, key, payload);
};
const loadGame = (slot) => {
  const parsed = runtimeSaveSlotsByKey?.[slotKey(slot)] || null;
  return parsed && Array.isArray(parsed.fields) ? cloneSaveSlotPayload(parsed) : null;
};
const findFirstEmptySaveSlot = () => {
  for (let slot = 0; slot < SAVE_SLOTS.length; slot += 1) {
    if (!loadGame(slot)) return slot;
  }
  return null;
};
