const mergeChatMessages = (prevMessages, incomingMessages) => {
  const parseChatTimestamp = (value) => {
    if (value instanceof Date) {
      const ms = value.getTime();
      return Number.isFinite(ms) ? ms : 0;
    }
    const raw = String(value ?? '').trim();
    if (!raw) return 0;
    const numeric = Number(raw);
    if (Number.isFinite(numeric) && numeric > 0) return numeric;
    const parsed = Date.parse(raw);
    return Number.isFinite(parsed) ? parsed : 0;
  };
  const mergedMap = new Map();
  const pushMessage = (message) => {
    const id = String(message?.id || '').trim();
    const username = String(message?.username || '').trim();
    const text = String(message?.text || '').trim();
    const createdAt = parseChatTimestamp(message?.createdAt);
    if (!id || !username || !text || createdAt <= 0) return;
    mergedMap.set(id, {
      id,
      username,
      text,
      createdAt
    });
  };
  (Array.isArray(prevMessages) ? prevMessages : []).forEach(pushMessage);
  (Array.isArray(incomingMessages) ? incomingMessages : []).forEach(pushMessage);
  return [...mergedMap.values()]
    .sort((a, b) => {
      if (a.createdAt !== b.createdAt) return a.createdAt - b.createdAt;
      return a.id.localeCompare(b.id, 'ko');
    })
    .slice(-CHAT_HISTORY_LIMIT);
};
const removeChatMessageById = (messages, messageId) => {
  const targetId = String(messageId || '').trim();
  if (!targetId) return Array.isArray(messages) ? messages : [];
  return (Array.isArray(messages) ? messages : []).filter((message) => (
    String(message?.id || '').trim() !== targetId
  ));
};
const formatChatTime = (value) => {
  const raw = String(value ?? '').trim();
  const numeric = Number(raw);
  const timestamp = Number.isFinite(numeric) && numeric > 0
    ? numeric
    : Date.parse(raw);
  if (timestamp <= 0) return '-';
  try {
    return new Intl.DateTimeFormat('ko-KR', {
      hour: '2-digit',
      minute: '2-digit',
      hour12: false
    }).format(new Date(timestamp));
  } catch {
    return '-';
  }
};
