const parseRuleMarkdownDocument = (raw = '') => {
  const lines = String(raw || '').replace(/\r/g, '').split('\n');
  const doc = {
    title: '',
    intro: [],
    sections: []
  };
  let currentSection = null;
  let inCodeBlock = false;
  let currentCodeLines = [];

  const ensureSection = () => {
    if (currentSection) return currentSection;
    currentSection = {
      heading: '',
      paragraphs: [],
      bullets: [],
      codeBlocks: []
    };
    doc.sections.push(currentSection);
    return currentSection;
  };

  const flushCodeBlock = () => {
    if (!currentCodeLines.length) return;
    ensureSection().codeBlocks.push(currentCodeLines.join('\n').trim());
    currentCodeLines = [];
  };

  lines.forEach((line) => {
    const trimmed = String(line || '').trim();
    if (trimmed.startsWith('```')) {
      if (inCodeBlock) flushCodeBlock();
      inCodeBlock = !inCodeBlock;
      return;
    }
    if (inCodeBlock) {
      currentCodeLines.push(String(line || ''));
      return;
    }
    if (!trimmed) return;
    if (trimmed.startsWith('# ')) {
      doc.title = trimmed.replace(/^#\s+/, '').trim();
      return;
    }
    if (trimmed.startsWith('## ')) {
      currentSection = {
        heading: trimmed.replace(/^##\s+/, '').trim(),
        paragraphs: [],
        bullets: [],
        codeBlocks: []
      };
      doc.sections.push(currentSection);
      return;
    }
    if (trimmed.startsWith('- ')) {
      ensureSection().bullets.push(trimmed.replace(/^- /, '').trim());
      return;
    }
    if (currentSection) {
      currentSection.paragraphs.push(trimmed);
      return;
    }
    doc.intro.push(trimmed);
  });

  if (inCodeBlock) flushCodeBlock();

  return doc;
};

