const harvestAvgFruitWeightKgByQuality = (quality) => {
  const safeQuality = clamp(Number(quality) || 0, 0, 100);
  const steppedQuality = Math.round(safeQuality);
  const weightByQualityFloor = {
    0: 0.16,
    10: 0.18,
    20: 0.205,
    30: 0.235,
    40: 0.265,
    50: 0.295,
    60: 0.335,
    70: 0.39,
    80: 0.46,
    90: 0.56,
    100: 0.56
  };
  const qualityFloor = Math.max(0, Math.min(90, Math.floor(steppedQuality / 10) * 10));
  const nextQualityFloor = Math.min(100, qualityFloor + 10);
  const startWeight = Number(weightByQualityFloor[qualityFloor]) || 0.16;
  const endWeight = Number(weightByQualityFloor[nextQualityFloor]) || startWeight;
  if (nextQualityFloor === qualityFloor) return startWeight;
  const rangeRatio = clamp((steppedQuality - qualityFloor) / (nextQualityFloor - qualityFloor), 0, 1);
  return Number((startWeight + ((endWeight - startWeight) * rangeRatio)).toFixed(3));
};
const QUALITY_LABEL_WEIGHT_ROWS = (() => {
  const rows = [];
  for (let quality = 0; quality <= 100; quality += 1) {
    const label = qualityStateText(quality);
    const weight = harvestAvgFruitWeightKgByQuality(quality);
    rows.push({
      label,
      min: quality,
      max: quality,
      weight
    });
  }
  return rows;
})();

const CONTAINER_KEY_MIGRATION = {
  appleContainerYellow18kg: 'appleContainerYellow20kg',
  appleContainerGreen18kg: 'appleContainerGreen20kg'
};

const migrateContainerInventoryKeys = (inventory = {}) => {
  const next = { ...(inventory || {}) };
  Object.entries(CONTAINER_KEY_MIGRATION).forEach(([legacyKey, nextKey]) => {
    const legacyQty = Math.max(0, Number(next?.[legacyKey]) || 0);
    if (legacyQty > 0) {
      next[nextKey] = Math.max(0, Number(next?.[nextKey]) || 0) + legacyQty;
    }
    delete next[legacyKey];
  });
  return next;
};

const migrateContainerKeysByFieldMap = (raw = {}) => Object.entries(raw || {}).reduce((acc, [fieldId, inventory]) => {
  acc[fieldId] = migrateContainerInventoryKeys(inventory || {});
  return acc;
}, {});

const normalizeFieldScopedMap = (raw = {}) => {
  if (!raw || typeof raw !== 'object' || Array.isArray(raw)) return {};
  return Object.entries(raw).reduce((acc, [fieldIdRaw, entryRaw]) => {
    const fieldId = String(fieldIdRaw || '').trim();
    if (!fieldId) return acc;
    acc[fieldId] = entryRaw && typeof entryRaw === 'object' && !Array.isArray(entryRaw)
      ? { ...entryRaw }
      : {};
    return acc;
  }, {});
};

const normalizeFieldFacilityScopedMap = (raw = {}) => {
  if (!raw || typeof raw !== 'object' || Array.isArray(raw)) return {};
  return Object.entries(raw).reduce((acc, [fieldIdRaw, facilityMapRaw]) => {
    const fieldId = String(fieldIdRaw || '').trim();
    if (!fieldId || !facilityMapRaw || typeof facilityMapRaw !== 'object' || Array.isArray(facilityMapRaw)) return acc;
    const migratedByFacility = Object.entries(facilityMapRaw).reduce((facilityAcc, [facilityKeyRaw, inventoryRaw]) => {
      const facilityKey = String(facilityKeyRaw || '').trim();
      if (!facilityKey) return facilityAcc;
      facilityAcc[facilityKey] = migrateContainerInventoryKeys(inventoryRaw || {});
      return facilityAcc;
    }, {});
    const normalizedByFacility = normalizeFacilityScopedMap(migratedByFacility);
    if (Object.keys(normalizedByFacility).length > 0) acc[fieldId] = normalizedByFacility;
    return acc;
  }, {});
};

const normalizeHarvestPalletMemoByFieldMap = (raw = {}) => {
  if (!raw || typeof raw !== 'object' || Array.isArray(raw)) return {};
  return Object.entries(raw).reduce((fieldAcc, [fieldIdRaw, facilityMapRaw]) => {
    const fieldId = String(fieldIdRaw || '').trim();
    if (!fieldId || !facilityMapRaw || typeof facilityMapRaw !== 'object' || Array.isArray(facilityMapRaw)) return fieldAcc;
    const byFacility = Object.entries(facilityMapRaw).reduce((facilityAcc, [facilityKeyRaw, slotMapRaw]) => {
      const facilityKey = String(facilityKeyRaw || '').trim();
      if (!facilityKey || !slotMapRaw || typeof slotMapRaw !== 'object' || Array.isArray(slotMapRaw)) return facilityAcc;
      const bySlot = Object.entries(slotMapRaw).reduce((slotAcc, [slotNoRaw, memoRaw]) => {
        const slotNo = Math.max(1, Math.floor(Number(slotNoRaw) || 0));
        if (slotNo <= 0) return slotAcc;
        const nextEntry = resolveHarvestPalletMemoSlot(memoRaw);
        if (!nextEntry) return slotAcc;
        slotAcc[slotNo] = nextEntry;
        return slotAcc;
      }, {});
      if (Object.keys(bySlot).length > 0) facilityAcc[facilityKey] = bySlot;
      return facilityAcc;
    }, {});
    if (Object.keys(byFacility).length > 0) fieldAcc[fieldId] = byFacility;
    return fieldAcc;
  }, {});
};

