          palletMemoColor: normalizeHarvestPalletMemoColor(topLayer?.palletMemoColor),
          loadBoxKey: String(topLayer?.loadBoxKey || ''),
          boxTone: String(topLayer?.boxTone || ''),
          filledBoxTones: Array.isArray(topLayer?.filledBoxTones) ? topLayer.filledBoxTones : [],
          filledBoxSlotTones: Array.isArray(topLayer?.filledBoxSlotTones) ? topLayer.filledBoxSlotTones : [],
          partialBoxTones: Array.isArray(topLayer?.partialBoxTones) ? topLayer.partialBoxTones : [],
          storagePalletBoxCount: Math.max(0, Math.floor(Number(topLayer?.storagePalletBoxCount) || 0)),
          storagePalletPartialBoxCount: Math.max(0, Math.floor(Number(topLayer?.storagePalletPartialBoxCount) || 0)),
          storagePalletRemainderKg: Math.max(0, Number(topLayer?.storagePalletRemainderKg) || 0),
