      floorBoxCount: visualBoxCount,
      floorBoxText: String(floorRow?.boxText || ''),
      floorDetailText: String(floorRow?.detailText || ''),
      floorFillLabel: String(floorRow?.fillLabel || ''),
      floorFillRatio: Math.max(0, Math.min(1, Number(floorRow?.fillRatio) || 0)),
      floorQualityLabel: String(floorRow?.qualityLabel || '보통'),
