      annualRate: Math.max(0, Number(item?.annualRate) || 0),
      monthsTotal: Math.max(1, Math.floor(Number(item?.monthsTotal) || LOAN_TERM_MONTHS)),
      monthsPaid: Math.max(0, Math.floor(Number(item?.monthsPaid) || 0)),
