const pollinationPollenNeedGramsByLabor = (field, day, laborToUse, selectedAgeYear = null) => {
  const labor = Math.max(0, Number(laborToUse) || 0);
  if (labor <= 0) return 0;
  const rows = cropRowsByVarietyAndAge(field, day, CROPS).filter((row) => (Number(row?.aliveTrees) || 0) > 0);
  if (!rows.length) return 0;
  const workedByAge = field?.ageTaskWorkedTreesByTask?.pollination || {};
  const laborCapTrees = Math.max(0, labor / POLLINATION_LABOR_PER_TREE);
  if (selectedAgeYear) {
    const ageKey = `${Math.max(1, Math.floor(Number(selectedAgeYear) || 1))}`;
    const row = rows.find((x) => `${Math.max(1, Math.floor(Number(x?.ageYear) || 1))}` === ageKey);
    const alive = Math.max(0, Number(row?.aliveTrees) || 0);
    const worked = Math.max(0, Number(workedByAge?.[ageKey]) || 0);
    const remain = Math.max(0, alive - worked);
    const treesToProcess = Math.min(remain, laborCapTrees);
    return Math.max(0, Math.ceil(treesToProcess * POLLEN_GRAMS_PER_TREE));
  }
  const remainTotal = rows.reduce((sum, row) => {
    const ageKey = `${Math.max(1, Math.floor(Number(row?.ageYear) || 1))}`;
    const alive = Math.max(0, Number(row?.aliveTrees) || 0);
    const worked = Math.max(0, Number(workedByAge?.[ageKey]) || 0);
    return sum + Math.max(0, alive - worked);
  }, 0);
  const treesToProcess = Math.min(remainTotal, laborCapTrees);
  return Math.max(0, Math.ceil(treesToProcess * POLLEN_GRAMS_PER_TREE));
};
const sprayLitersPerTreeByAgeYear = (ageYear) => {
  const age = Math.max(1, Math.floor(Number(ageYear) || 1));
  if (age <= 1) return 1;
  if (age === 2) return 2;
  if (age === 3) return 3;
  return 4;
};
const herbicideSprayLitersPerTree = () => {
  const herbicideKeys = ['pesticideGlyphosate', 'pesticideGlufosinate', 'pesticideStomp'];
  const liters = herbicideKeys
    .map((key) => Math.max(0, Number(SPRAY_LITERS_PER_TREE_BY_PESTICIDE?.[key]) || 0))
    .filter((v) => v > 0);
  if (!liters.length) return 0.05;
  return Math.min(...liters);
};
const sprayNeedLitersForField = (field, day, taskKey = '') => {
  if (String(taskKey || '') === 'herbicideSpray') {
    const aliveTrees = Math.max(0, liveTreeCount(field));
    return Math.max(0, Math.ceil(aliveTrees * herbicideSprayLitersPerTree()));
  }
  const rows = cropRowsByVarietyAndAge(field, day, CROPS);
  if (rows.length) {
    return rows.reduce(
      (sum, row) => sum + (Math.max(0, Number(row?.aliveTrees) || 0) * sprayLitersPerTreeByAgeYear(row?.ageYear)),
      0
    );
  }
  const aliveTrees = Math.max(0, liveTreeCount(field));
  return Math.max(0, Math.ceil(aliveTrees * sprayLitersPerTreeByAgeYear(treeAgeYear(field, day))));
};
const sprayNeedRemainingLitersForTask = (field, taskKey, day) => {
  const totalNeed = sprayNeedLitersForField(field, day, taskKey);
  if (!SPRAY_TASK_KEYS.includes(taskKey)) return totalNeed;
  const currentProgress = clamp(Number(field?.taskProgress?.[taskKey]) || 0, 0, 100);
  const remainRatio = Math.max(0, 1 - (currentProgress / 100));
  return Math.max(0, Math.ceil(totalNeed * remainRatio));
};
const pestIncreaseAgeMultiplier = (ageYear) => {
  const age = Math.max(1, Math.floor(Number(ageYear) || 1));
  if (age <= 1) return 0.1;
  if (age === 2) return 0.15;
  if (age === 3) return 0.65;
  return 1;
};
const PEST_EVENT_CHANCE_ANCHORS = [
  { pest: 30, chance: 0.05 },
  { pest: 50, chance: 0.12 },
  { pest: 75, chance: 0.26 },
  { pest: 100, chance: 0.40 }
];
const pestEventChanceByBase = (nextPestBaseRaw) => {
  const p = clamp(Number(nextPestBaseRaw) || 0, 0, 100);
  if (p < PEST_EVENT_CHANCE_ANCHORS[0].pest) return 0;
  for (let i = 0; i < PEST_EVENT_CHANCE_ANCHORS.length - 1; i += 1) {
    const from = PEST_EVENT_CHANCE_ANCHORS[i];
    const to = PEST_EVENT_CHANCE_ANCHORS[i + 1];
    if (p <= to.pest) {
      const ratio = clamp((p - from.pest) / Math.max(1, to.pest - from.pest), 0, 1);
      return from.chance + ((to.chance - from.chance) * ratio);
    }
  }
  return PEST_EVENT_CHANCE_ANCHORS[PEST_EVENT_CHANCE_ANCHORS.length - 1].chance;
};
const PEST_RAIN_WEATHER_BOOST_DAYS = 7;
const PEST_RAIN_WEATHER_BOOST_MULTIPLIER = 2.5;
const WEED_RAIN_WEATHER_BOOST_DAYS = 4;
const WEED_RAIN_WEATHER_BOOST_MULTIPLIER = 2.5;
const pestVigorPenaltyByLevel = (pest) => {
  const p = clamp(Number(pest) || 0, 0, 100);
  if (p < 30) return 0;
  if (p < 60) return ((p - 30) / 30) * 0.12;
  if (p < 80) return 0.12 + (((p - 60) / 20) * 0.28);
  return 0.40 + (((p - 80) / 20) * 0.60);
};
const severeWeedVigorPenaltyByLevel = (weed) => {
  const w = clamp(Number(weed) || 0, 0, 100);
  if (w < 70) return 0;
  if (w < 85) return ((w - 70) / 15) * 0.12;
  return 0.12 + (((w - 85) / 15) * 0.38);
};
const vigorGrowthAgeMultiplier = (ageYear) => {
  const age = Math.max(1, Math.floor(Number(ageYear) || 1));
  // 현실적인 완만 곡선: 유목기 높고, 성목기로 갈수록 점진 둔화, 노화기 완만 감소
  if (age <= 1) return 1.45;
  if (age === 2) return 1.35;
  if (age === 3) return 1.25;
  if (age === 4) return 1.12;
  if (age === 5) return 1.02;
  if (age === 6) return 0.80;
  if (age <= 8) return 0.65;
  if (age <= 10) return 0.52;
  if (age <= 12) return 0.42;
  if (age <= 15) return 0.32;
  if (age <= 20) return 0.20;
  if (age <= 25) return 0.08;
  return -0.08;
};
const vigorImpactAgeMultiplier = (ageYear) => {
  const age = Math.max(1, Math.floor(Number(ageYear) || 1));
  if (age <= 1) return 0.25;
  if (age === 2) return 0.45;
  if (age === 3) return 0.7;
  if (age === 4) return 0.85;
  return 1;
};
const pestIncreaseAgeMultiplierForField = (field, day) => {
  const rows = cropRowsByVarietyAndAge(field, day, CROPS);
  if (rows.length) {
    const weighted = rows.reduce((acc, row) => {
      const alive = Math.max(0, Number(row?.aliveTrees) || 0);
      if (alive <= 0) return acc;
      return {
        trees: acc.trees + alive,
        sum: acc.sum + (alive * pestIncreaseAgeMultiplier(row?.ageYear))
      };
    }, { trees: 0, sum: 0 });
    if (weighted.trees > 0) return weighted.sum / weighted.trees;
  }
  return pestIncreaseAgeMultiplier(treeAgeYear(field, day));
};
const vigorImpactAgeMultiplierForField = (field, day) => {
  const rows = cropRowsByVarietyAndAge(field, day, CROPS);
  if (rows.length) {
    const weighted = rows.reduce((acc, row) => {
      const alive = Math.max(0, Number(row?.aliveTrees) || 0);
      if (alive <= 0) return acc;
      return {
        trees: acc.trees + alive,
        sum: acc.sum + (alive * vigorImpactAgeMultiplier(row?.ageYear))
      };
    }, { trees: 0, sum: 0 });
    if (weighted.trees > 0) return weighted.sum / weighted.trees;
  }
  return vigorImpactAgeMultiplier(treeAgeYear(field, day));
};
const pruningVigorShockAgeMultiplier = (ageYear, taskKey = 'winterPruning') => {
  const age = Math.max(1, Math.floor(Number(ageYear) || 1));
  if (WINTER_PRUNING_TASK_KEYS.has(String(taskKey || ''))) {
    return winterPruningAgeEffectMultiplier(age);
  }
  if (WATERSPROUT_PRUNING_TASK_KEYS.has(String(taskKey || ''))) {
    if (age <= 1) return 0.12;
    if (age === 2) return 0.2;
    if (age === 3) return 0.55;
    if (age <= 8) return 1.0;
    return 0.85;
  }
  if (age <= 3) return 1.2;
  if (age <= 8) return 1.0;
  return 0.85;
};
const pruningVigorShockAgeMultiplierForField = (field, day, taskKey = 'winterPruning') => {
  const rows = cropRowsByVarietyAndAge(field, day, CROPS);
  if (rows.length) {
    const weighted = rows.reduce((acc, row) => {
      const alive = Math.max(0, Number(row?.aliveTrees) || 0);
      if (alive <= 0) return acc;
      return {
        trees: acc.trees + alive,
        sum: acc.sum + (alive * pruningVigorShockAgeMultiplier(row?.ageYear, taskKey))
      };
    }, { trees: 0, sum: 0 });
    if (weighted.trees > 0) return weighted.sum / weighted.trees;
  }
  return pruningVigorShockAgeMultiplier(treeAgeYear(field, day), taskKey);
};
const vigorGrowthAgeMultiplierForField = (field, day) => {
  const rows = cropRowsByVarietyAndAge(field, day, CROPS);
  if (rows.length) {
    const weighted = rows.reduce((acc, row) => {
      const alive = Math.max(0, Number(row?.aliveTrees) || 0);
      if (alive <= 0) return acc;
      return {
        trees: acc.trees + alive,
        sum: acc.sum + (alive * vigorGrowthAgeMultiplier(row?.ageYear))
      };
    }, { trees: 0, sum: 0 });
    if (weighted.trees > 0) return weighted.sum / weighted.trees;
  }
  return vigorGrowthAgeMultiplier(treeAgeYear(field, day));
};
const FRUIT_LOAD_VIGOR_DELTA_PER_UNIT = 0.09;
const FRUIT_LOAD_VIGOR_DELTA_MAX = 0.22;
const FRUIT_LOAD_VIGOR_BASE_DRIFT = -0.02;
