const fruitLoadVigorDeltaByAgeForField = (field, day) => {
  const rows = cropRowsByVarietyAndAge(field, day, CROPS);
  if (!rows.length) return 0;
  const progress = seasonalFruitLoadProgress(day);
  const weighted = rows.reduce((acc, row) => {
    const alive = Math.max(0, Number(row?.aliveTrees) || 0);
    if (alive <= 0) return acc;
    const ageYear = Math.max(1, Math.floor(Number(row?.ageYear) || 1));
    const profile = fruitLoadProfileForAge(ageYear);
    const [optMinRaw, optMaxRaw] = Array.isArray(profile?.optimal) ? profile.optimal : [0, 0];
    const seasonalMin = Math.max(0, Number(optMinRaw) || 0) * progress;
    const seasonalMax = Math.max(seasonalMin, (Math.max(0, Number(optMaxRaw) || 0) * progress));
    const target = (seasonalMin + seasonalMax) / 2;
    const halfBand = Math.max(1, (seasonalMax - seasonalMin) / 2);
    const load = fruitLoadPerTreeForAgeRow(field, row, day);
    const normalizedGap = clamp((load - target) / halfBand, -2.5, 2.5);
    const overload = fruitOverloadStatusByAge(ageYear, load);
    const overloadDecayMultiplier = normalizedGap > 0
      ? (FRUIT_LOAD_VIGOR_OVERLOAD_DECAY_MULTIPLIER_BY_LEVEL?.[overload?.level] || FRUIT_LOAD_VIGOR_OVERLOAD_DECAY_MULTIPLIER)
      : 1;
    const rawAgeDelta = (-normalizedGap * FRUIT_LOAD_VIGOR_DELTA_PER_UNIT * overloadDecayMultiplier) + FRUIT_LOAD_VIGOR_BASE_DRIFT;
    const ageDelta = clamp(
      rawAgeDelta,
      -(FRUIT_LOAD_VIGOR_DELTA_MAX * overloadDecayMultiplier),
      FRUIT_LOAD_VIGOR_DELTA_MAX
    );
    return {
      trees: acc.trees + alive,
      sum: acc.sum + (ageDelta * alive)
    };
  }, { trees: 0, sum: 0 });
  if (weighted.trees <= 0) return 0;
  return weighted.sum / weighted.trees;
};
const nextHarvestDayOfField = (field, day) => {
  if (!field?.cropId) return 0;
  const startDay = Math.max(1, Math.floor(Number(day) || 1));
  const searchEndDay = startDay + 500;
  for (let targetDay = startDay; targetDay <= searchEndDay; targetDay += 1) {
    const growth = calendarGrowthPercent(targetDay, field.lastHarvestYear, field?.cropId);
    if (growth >= 99.5 && growth < 99.9) return targetDay;
  }
  return 0;
};
const shouldShowQualityHintByHarvestWindow = (field, day) => {
  if (!field?.cropId) return false;
  if (growthStageLabel(field) === '수확기') return true;
  const currentDay = Math.max(1, Math.floor(Number(day) || 1));
  const harvestDay = nextHarvestDayOfField(field, currentDay);
  if (harvestDay <= 0) return false;
  return currentDay >= (harvestDay - HARVEST_QUALITY_HINT_DAYS_BEFORE) && currentDay <= harvestDay;
};
