const facilityCost = (facility, game, fieldIndex = null) => {
  if (facility?.key === 'frostFan') {
    if (fieldIndex !== null && game?.fields?.[fieldIndex]) {
      return frostFanCostByField(facility, game.fields[fieldIndex]);
    }
    const ownedFields = (game?.fields || []).filter((field) => field?.owned);
    if (!ownedFields.length) return Number(facility?.price) || 0;
    return Math.min(...ownedFields.map((field) => frostFanCostByField(facility, field)));
  }
  if (IRRIGATION_FACILITY_KEYS.includes(facility?.key)) {
    if (fieldIndex !== null && game?.fields?.[fieldIndex]) {
      const unassignedTrees = fieldIrrigationUnassignedTrees(game.fields[fieldIndex]);
      return unassignedTrees * (Number(facility?.unitPricePerTree) || 0);
    }
    const unassignedTrees = totalIrrigationUnassignedTrees(game);
    return unassignedTrees * (Number(facility?.unitPricePerTree) || 0);
  }
  if (!facility?.perTree) return Number(facility?.price) || 0;
  const unitPrice = Number(facility?.unitPricePerTree) || 0;
  if (fieldIndex !== null && game?.fields?.[fieldIndex]) {
    const assignableTrees = fieldPerTreeFacilityUnassignedTrees(game.fields[fieldIndex], facility.key);
    return assignableTrees * unitPrice;
  }
  const assignableTrees = (game?.fields || []).reduce(
    (sum, field) => (field.owned ? sum + fieldPerTreeFacilityUnassignedTrees(field, facility.key) : sum),
    0
  );
  return assignableTrees * unitPrice;
};
