const escapeAnimationLabAttr = (value) => String(value || '').replace(/"/g, '&quot;');
const toAnimationLabNumber = (value, fallback = 0) => {
  const n = Number(value);
  return Number.isFinite(n) ? n : fallback;
};
const parseAnimationLabTranslate = (value) => {
  const src = String(value || '').trim();
  if (!src) return { x: 0, y: 0 };
  const parts = src.split(/\s+/).map((v) => Number.parseFloat(String(v).replace('px', '')));
  return {
    x: Number.isFinite(parts[0]) ? parts[0] : 0,
    y: Number.isFinite(parts[1]) ? parts[1] : 0
  };
};
const parseAnimationLabScale = (value) => {
  const src = String(value || '').trim();
  if (!src) return 1;
  const n = Number.parseFloat(src);
  if (!Number.isFinite(n)) return 1;
  return clamp(n, 0.1, 10);
};
const parseAnimationLabOpacity = (value) => {
  const src = String(value || '').trim();
  if (!src) return 1;
  const n = Number.parseFloat(src);
  if (!Number.isFinite(n)) return 1;
  return clamp(n, 0, 1);
};
const applyAnimationLabElementTransform = (target, tx = 0, ty = 0, scaleX = 1, scaleY = 1, rotate = 0) => {
  if (!target) return;
  const base = String(target.getAttribute(ANIMATION_LAB_EDITOR_BASE_TRANSFORM_ATTR) || '').trim();
  const transforms = [`translate(${Number(tx).toFixed(2)}px, ${Number(ty).toFixed(2)}px)`];
  const normalizedRotate = clamp(Number(rotate) || 0, -360, 360);
  if (Math.abs(normalizedRotate) > 0.0001) transforms.push(`rotate(${normalizedRotate.toFixed(2)}deg)`);
  const normalizedScaleX = clamp(Number(scaleX) || 1, 0.2, 4);
  const normalizedScaleY = clamp(Number(scaleY) || 1, 0.2, 4);
  if (Math.abs(normalizedScaleX - normalizedScaleY) < 0.0001) {
    if (Math.abs(normalizedScaleX - 1) > 0.0001) transforms.push(`scale(${normalizedScaleX.toFixed(4)})`);
  } else {
    transforms.push(`scale(${normalizedScaleX.toFixed(4)}, ${normalizedScaleY.toFixed(4)})`);
  }
  if (base && base !== 'none') transforms.push(base);
  target.style.transform = transforms.join(' ');
};
const applyAnimationLabElementOpacity = (target, opacity = 1) => {
  if (!target) return;
  const normalizedOpacity = clamp(Number(opacity) || 0, 0, 1);
  if (Math.abs(normalizedOpacity - 1) < 0.0001) {
    target.style.opacity = '';
    return;
  }
  target.style.opacity = normalizedOpacity.toFixed(2);
};
const stripAnimationLabOverlayFromHtml = (html) => {
  const src = String(html || '');
  if (!src.includes('animation-lab-overlay-root')) return src;
  try {
    const parser = new DOMParser();
    const doc = parser.parseFromString(src, 'text/html');
    doc.getElementById('animation-lab-overlay-root')?.remove();
    return `<!DOCTYPE html>\n${doc.documentElement.outerHTML}`;
  } catch {
    return src;
  }
};
const injectAnimationLabOverlayIntoHtml = (html, layers, canvas) => {
  const src = stripAnimationLabOverlayFromHtml(html);
  if (!Array.isArray(layers) || !layers.length) return src;
  const width = Math.max(100, Math.round(toAnimationLabNumber(canvas?.width, 1000)));
  const height = Math.max(100, Math.round(toAnimationLabNumber(canvas?.height, 1000)));
  const lines = layers.map((layer) => {
    const x1 = toAnimationLabNumber(layer?.x1, 0).toFixed(2);
    const y1 = toAnimationLabNumber(layer?.y1, 0).toFixed(2);
    const x2 = toAnimationLabNumber(layer?.x2, 0).toFixed(2);
    const y2 = toAnimationLabNumber(layer?.y2, 0).toFixed(2);
    const widthPx = Math.max(1, toAnimationLabNumber(layer?.width, 4)).toFixed(2);
    const opacity = clamp(toAnimationLabNumber(layer?.opacity, 1), 0, 1).toFixed(3);
    const color = escapeAnimationLabAttr(layer?.color || '#1a1a1a');
    return `<line x1="${x1}" y1="${y1}" x2="${x2}" y2="${y2}" stroke="${color}" stroke-width="${widthPx}" stroke-linecap="round" opacity="${opacity}" />`;
  }).join('');
  const overlay = `
<div id="animation-lab-overlay-root" style="position:fixed;inset:0;pointer-events:none;z-index:2147483646;">
  <svg viewBox="0 0 ${width} ${height}" width="100%" height="100%" preserveAspectRatio="none" style="display:block;overflow:visible;">
    ${lines}
  </svg>
</div>`;
  const bodyClose = src.lastIndexOf('</body>');
  if (bodyClose >= 0) {
    return `${src.slice(0, bodyClose)}${overlay}\n${src.slice(bodyClose)}`;
  }
  return `${src}\n${overlay}`;
};

function getSevenSegmentCharParts(char) {
  const digitSegments = {
    '0': ['a', 'b', 'c', 'd', 'e', 'f'],
    '1': ['b', 'c'],
    '2': ['a', 'b', 'd', 'e', 'g'],
    '3': ['a', 'b', 'c', 'd', 'g'],
    '4': ['b', 'c', 'f', 'g'],
    '5': ['a', 'c', 'd', 'f', 'g'],
    '6': ['a', 'c', 'd', 'e', 'f', 'g'],
    '7': ['a', 'b', 'c'],
    '8': ['a', 'b', 'c', 'd', 'e', 'f', 'g'],
    '9': ['a', 'b', 'c', 'd', 'f', 'g']
  };
  if (char === '.') return { type: 'dot' };
  if (char === '-') return { type: 'minus' };
  return {
    type: 'digit',
    activeSegments: digitSegments[char] ?? []
  };
}

