    const currentOwnedQty = Math.max(0, Number(game.inventory?.[item.key]) || 0);
    const maxCanAdd = item.maxQty ? Math.max(0, item.maxQty - currentOwnedQty) : 9999;
    if (maxCanAdd <= 0) return;
    const cartKey = String(options?.cartKey || item.key);
