    const slotCount = activeTownMarkerParkingSlotCountOf(destinationKey);
    const slotNo = Math.max(1, Math.min(slotCount, Math.floor(Number(slotNoRaw) || 1)));
    if (!destinationKey) return;
    const safeCooldownMs = Math.max(0, Number(cooldownMs) || 0);
    const expiresAt = Date.now() + safeCooldownMs;
    setTownParkingNpcBusyCooldownByKey((prev) => {
      const nextByKey = { ...(prev || {}) };
      nextByKey[destinationKey] = {
        ...(nextByKey[destinationKey] || {}),
        [slotNo]: expiresAt
      };
      return nextByKey;
    });
    window.setTimeout(() => {
      setTownParkingNpcBusyCooldownByKey((prev) => {
        const currentExpiresAt = Number(prev?.[destinationKey]?.[slotNo] || 0);
        if (currentExpiresAt !== expiresAt) return prev;
        const nextByKey = { ...(prev || {}) };
        const nextSlots = { ...(nextByKey[destinationKey] || {}) };
        delete nextSlots[slotNo];
        if (Object.keys(nextSlots).length > 0) {
          nextByKey[destinationKey] = nextSlots;
        } else {
          delete nextByKey[destinationKey];
        }
        return nextByKey;
      });
    }, safeCooldownMs + 50);
