    const hasSelectedExcavator = selectedFieldParkedExcavatorInstances.some((machine) => String(machine?.id || '') === String(currentChoice.excavatorInstanceId || ''));
    if (hasSelectedExcavator) return;
    const fallbackExcavatorId = String(selectedFieldParkedExcavatorInstances[0]?.id || '');
