    const pxPerKm = setupLandMapPxPerKm();
    const nextX = drag.centerX - ((dx / pxPerKm) * EXTERNAL_MAP_PAN_SPEED);
    const nextY = drag.centerY - ((dy / pxPerKm) * EXTERNAL_MAP_PAN_SPEED);
