        sourceBoxUnitNo: Math.max(0, Math.floor(Number(resolvedSourceBoxCard?.sourceBoxUnitNo) || 0)),
        sourceBatchIds: Array.isArray(resolvedSourceBoxCard?.sourceBatchIds)
