  const devWarehouseAddTabOptions = useMemo(() => ([
    ['all', '전체'],
    ['tool', '도구'],
    ['machine', '작업장비'],
    ['transport', '운반장비'],
    ['passenger', '차량'],
    ['harvest', '수확물'],
    ['container', '컨테이너'],
    ['consumableMaterial', '자재'],
    ['pesticide', '농약'],
    ['pollen', '꽃가루'],
    ['fertilizer', '비료'],
    ['seedling', '묘목']
  ]), []);
  const devWarehouseAddCategoryKeyOf = useCallback((item) => {
    const baseCategory = String(itemCategoryByKey?.[String(item?.key || '')] || item?.category || '');
    if (baseCategory === 'machine') {
      const type = String(item?.type || '');
      if (type === 'transport') return 'transport';
      if (type === 'passenger') return 'passenger';
      return 'machine';
    }
    return baseCategory || 'all';
  }, [itemCategoryByKey]);
  const devWarehouseAddItems = useMemo(() => {
    const keyword = String(devWarehouseAddSearch || '').trim().toLowerCase();
    return Object.values(itemMetaByKey || {})
      .filter((item) => item && String(item?.key || ''))
      .filter((item) => String(item?.category || itemCategoryByKey?.[String(item?.key || '')] || '') !== 'fuel')
      .filter((item) => !SHOP_HIDDEN_ITEM_KEYS.has(String(item?.key || '')))
      .filter((item) => {
        if (devWarehouseAddTab === 'all') return true;
        return devWarehouseAddCategoryKeyOf(item) === devWarehouseAddTab;
      })
      .filter((item) => {
        if (!keyword) return true;
        const haystack = [
          String(item?.name || ''),
          String(item?.desc || ''),
          String(item?.key || '')
        ].join(' ').toLowerCase();
        return haystack.includes(keyword);
      })
      .sort((a, b) => String(a?.name || '').localeCompare(String(b?.name || ''), 'ko'));
  }, [devWarehouseAddSearch, devWarehouseAddTab, devWarehouseAddCategoryKeyOf, itemCategoryByKey, itemMetaByKey]);
  const carrierIsTruck = useCallback(
    (carrier) => String(carrier?.item?.type || '') === 'transport',
    []
  );
  const resolveItemMetaForLoad = useCallback(
    (itemKey, itemLike = null) => {
      const key = String(itemKey || itemLike?.key || '');
      if (!key) return {};
      if (itemLike && typeof itemLike === 'object') return { ...(itemMetaByKey?.[key] || {}), ...itemLike };
      return itemMetaByKey?.[key] || {};
    },
    [itemMetaByKey]
  );
  const resolveItemCategoryForLoad = useCallback(
    (itemKey, itemLike = null, itemCategory = '') => {
      const byArg = String(itemCategory || '');
      if (byArg) return byArg;
      const byItem = String(itemLike?.category || '');
      if (byItem) return byItem;
      return String(itemCategoryByKey?.[String(itemKey || itemLike?.key || '')] || '');
    },
    [itemCategoryByKey]
  );
  const isFarmMachineItem = useCallback((itemMeta, category) => {
    if (String(category || '') !== 'machine') return false;
    const type = String(itemMeta?.type || '');
    return FARM_MACHINE_TYPES.has(type);
  }, []);
  const isPortableSprayerItem = useCallback((itemMeta) => {
    return isFarmMartMachineItem(itemMeta);
  }, []);
  const isPortableCarryMachineItem = useCallback((itemMeta) => {
    return isPortableSprayerItem(itemMeta) || isShoulderBrushMachineItem(itemMeta);
  }, [isPortableSprayerItem]);
  const truckOnlyReasonOfItem = useCallback((itemMeta, category) => {
    if (isPortableCarryMachineItem(itemMeta)) return '';
    if (isFarmMachineItem(itemMeta, category)) return '농기계는 화물차 적재함에만 실을 수 있습니다.';
    const itemKey = String(itemMeta?.key || '');
    if (itemKey.startsWith('carrierLadder')) return '농기계 운반용 사다리는 화물차에만 적재할 수 있습니다.';
    const weightKg = Math.max(0, Number(itemMeta?.weightKg) || 0);
    if (weightKg >= TRUCK_ONLY_ITEM_WEIGHT_KG) return '해당 화물은 화물차 적재함에서만 이동할 수 있습니다.';
    return '';
  }, [isFarmMachineItem, isPortableCarryMachineItem]);
  const minRequiredLadderCapacityKg = useCallback((machineWeightKg) => {
    const safeWeight = Math.max(0, Number(machineWeightKg) || 0);
    if (safeWeight <= 500) return 500;
    if (safeWeight <= 1000) return 1000;
    if (safeWeight <= 1500) return 1500;
    if (safeWeight <= 2000) return 2000;
    if (safeWeight <= 2500) return 2500;
    if (safeWeight <= 3500) return 3500;
    return 5500;
  }, []);
  const availableCarrierLadderCount = useCallback((carrierCargoByKey, minCapacityKg) => {
    const cargo = carrierCargoByKey && typeof carrierCargoByKey === 'object' ? carrierCargoByKey : {};
    return Object.entries(CARRIER_LADDER_CAPACITY_KG_BY_KEY).reduce((sum, [ladderKey, capacityKg]) => {
      if (capacityKg < minCapacityKg) return sum;
      return sum + Math.max(0, Math.floor(Number(cargo?.[ladderKey]) || 0));
    }, 0);
  }, []);
  const validateCarrierLoadRule = useCallback(({
    carrier,
    carrierCargoByKey,
    itemKey,
    itemLike,
    itemCategory
  }) => {
    const itemMeta = resolveItemMetaForLoad(itemKey, itemLike);
    const category = resolveItemCategoryForLoad(itemKey, itemLike, itemCategory);
    const truckOnlyReason = truckOnlyReasonOfItem(itemMeta, category);
    if (truckOnlyReason && !carrierIsTruck(carrier)) return truckOnlyReason;
    if (isPortableCarryMachineItem(itemMeta)) return '';
    if (!isFarmMachineItem(itemMeta, category)) return '';
    const machineWeightKg = Math.max(0, Number(itemMeta?.weightKg) || 0);
    const minLadderCapacityKg = minRequiredLadderCapacityKg(machineWeightKg);
    if (machineWeightKg > 5500) {
      return '5.5톤용 사다리로도 부족한 중량입니다. 더 높은 규격의 운반 수단이 필요합니다.';
    }
    const ladderCount = availableCarrierLadderCount(carrierCargoByKey, minLadderCapacityKg);
    if (ladderCount < 2) {
      return `농기계 적재에는 ${Math.round(minLadderCapacityKg / 1000 * 10) / 10}톤급 이상 운반 사다리 2개가 필요합니다.`;
    }
    return '';
  }, [
    availableCarrierLadderCount,
    carrierIsTruck,
    isFarmMachineItem,
    isPortableCarryMachineItem,
    minRequiredLadderCapacityKg,
    resolveItemCategoryForLoad,
    resolveItemMetaForLoad,
    truckOnlyReasonOfItem
  ]);
  const machineRefuelCanSourceSections = useMemo(() => {
    if (!game || !machineRefuelFuelKey) return [];
    const containerMetaByKey = (Array.isArray(SHOP_ITEMS?.container) ? SHOP_ITEMS.container : [])
      .reduce((acc, item) => ({ ...acc, [String(item?.key || '')]: item || null }), {});
    const seenCarrierIds = new Set();
    const parkedCarrierSources = selectedFieldParkingSlots
      .map((instanceId, idx) => {
        const carrier = instanceId ? resolveMachineInstanceById(instanceId) : null;
        const carrierId = String(carrier?.id || '');
        if (!carrierId || seenCarrierIds.has(carrierId)) return null;
        seenCarrierIds.add(carrierId);
        if ((Number(carrier?.item?.payloadKg) || 0) <= 0) return null;
        return {
          key: `vehicle:${carrierId}`,
          title: `현재 토지 차량 적재함(P${idx + 1})`,
          cargoByKey: game?.vehicleCargoByInstance?.[carrierId] || {},
          fuelByItemKey: Object.entries(game?.vehicleFuelStorageByInstance?.[carrierId] || {})
            .reduce((acc, [itemKeyRaw, fuelMapRaw]) => {
              const itemKey = String(itemKeyRaw || '');
              if (!itemKey) return acc;
              const remain = floorLitersToStep(fuelMapRaw?.[machineRefuelFuelKey]);
              if (remain <= 0) return acc;
              return { ...acc, [itemKey]: remain };
            }, {})
        };
      })
      .filter(Boolean);
    const sourceDefs = [
      {
        key: 'warehouse',
        title: '현재 토지 창고',
        cargoByKey: game?.inventory || {},
        fuelByItemKey: Object.entries(game?.fuelStorageByContainer || {})
          .reduce((acc, [itemKeyRaw, fuelMapRaw]) => {
            const itemKey = String(itemKeyRaw || '');
            if (!itemKey) return acc;
            const remain = floorLitersToStep(fuelMapRaw?.[machineRefuelFuelKey]);
            if (remain <= 0) return acc;
            return { ...acc, [itemKey]: remain };
          }, {})
      },
      ...parkedCarrierSources
    ];
    return sourceDefs
      .map((source) => {
        const options = Object.entries(source.cargoByKey || {})
          .flatMap(([itemKeyRaw, qtyRaw]) => {
            const itemKey = String(itemKeyRaw || '');
            const qty = Math.max(0, Math.floor(Number(qtyRaw) || 0));
            if (!itemKey || qty <= 0) return [];
            const canonicalItemKey = normalizeFuelContainerKey(itemKey) || itemKey;
            const itemMeta = containerMetaByKey[itemKey] || containerMetaByKey[canonicalItemKey] || itemMetaByKey?.[itemKey] || itemMetaByKey?.[canonicalItemKey] || {};
            const cap = Math.max(
              0,
              containerCapacityLitersOfItem(itemMeta)
              || parseCapacityLitersFromText(itemMeta?.name)
              || parseCapacityLitersFromText(itemKey)
              || 0
            );
            if (cap <= 0) return [];
            const totalRemain = floorLitersToStep(
              source.fuelByItemKey?.[itemKey]
              ?? (canonicalItemKey !== itemKey ? source.fuelByItemKey?.[canonicalItemKey] : 0)
            );
            if (totalRemain <= 0) return [];
            const groupKey = `${source.key}:${itemKey}:${machineRefuelFuelKey}`;
            const defaultSplit = splitFuelLitersByCanCount(totalRemain, qty, cap);
            const customSplit = normalizeFuelCanSplit(
              fuelCanSplitByGroupSource?.[groupKey],
              qty,
              cap,
              floorLitersToStep(
                (fuelCanSplitByGroupSource?.[groupKey] || [])
                  .reduce((sum, liters) => sum + floorLitersToStep(liters), 0)
              )
            );
            const effectiveSplit = Array.isArray(customSplit) ? customSplit : defaultSplit;
            const canOptions = effectiveSplit
              .map((litersRaw, index) => {
                const liters = floorLitersToStep(litersRaw);
                if (liters <= 0) return null;
                return {
                  optionKey: `${source.key}:${itemKey}:${index}`,
                  sourceKey: source.key,
                  sourceTitle: source.title,
                  itemKey,
                  groupKey,
                  optionIndex: index,
                  groupQty: qty,
                  qty: 1,
                  cap,
                  fuelLiters: liters,
                  label: `말통 ${formatLiterTextFixed2(liters)}L/${formatLiterTextFixed2(cap)}L (${machineRefuelFuelTypeLabel})`
                };
              })
              .filter(Boolean);
            return canOptions;
          })
          .filter(Boolean);
        if (!options.length) return null;
        return {
          key: source.key,
          title: source.title,
          options
        };
      })
      .filter(Boolean);
  }, [game, machineRefuelFuelKey, machineRefuelFuelTypeLabel, selectedFieldParkingSlots, resolveMachineInstanceById, itemMetaByKey, fuelCanSplitByGroupSource]);
  useEffect(() => {
    if (!machineRefuelSelectedCan) return;
    const selectedOptionKey = String(machineRefuelSelectedCan?.optionKey || '');
    let matchedOption = null;
    machineRefuelCanSourceSections.some((section) => {
      const found = (section.options || []).find((option) => String(option?.optionKey || '') === selectedOptionKey);
      if (!found) return false;
      matchedOption = found;
      return true;
    });
    if (!matchedOption) {
      setMachineRefuelSelectedCan(null);
      return;
    }
    const nextFuelLiters = Math.max(0, Number(matchedOption?.fuelLiters) || 0);
    const nextCap = Math.max(0, Number(matchedOption?.cap) || 0);
    const nextLabel = String(matchedOption?.label || '');
    const nextGroupKey = String(matchedOption?.groupKey || '');
    const nextOptionIndex = Math.max(0, Number(matchedOption?.optionIndex) || 0);
    const nextGroupQty = Math.max(1, Number(matchedOption?.groupQty) || 1);
    const hasDiff = (
      Math.abs(nextFuelLiters - (Number(machineRefuelSelectedCan?.fuelLiters) || 0)) > 0.009
      || Math.abs(nextCap - (Number(machineRefuelSelectedCan?.cap) || 0)) > 0.009
      || nextLabel !== String(machineRefuelSelectedCan?.label || '')
      || nextGroupKey !== String(machineRefuelSelectedCan?.groupKey || '')
      || nextOptionIndex !== Math.max(0, Number(machineRefuelSelectedCan?.optionIndex) || 0)
      || nextGroupQty !== Math.max(1, Number(machineRefuelSelectedCan?.groupQty) || 1)
    );
    if (!hasDiff) return;
    setMachineRefuelSelectedCan((prev) => (prev ? {
      ...prev,
      label: nextLabel,
      cap: nextCap,
      fuelLiters: nextFuelLiters,
      groupKey: nextGroupKey,
      optionIndex: nextOptionIndex,
      groupQty: nextGroupQty
    } : prev));
  }, [machineRefuelCanSourceSections, machineRefuelSelectedCan]);
