      const isFullBox = qtyKg >= HARVEST_BOX_CAPACITY_KG - 0.001;
      const fillStep = isFullBox ? 3 : (((qtyKg / HARVEST_BOX_CAPACITY_KG) > (1 / 3)) ? 2 : 1);
      const groupKey = isFullBox
