      const groupKey = `${cropId}::${normalizedQuality}::${stemStatusKey}::${gradeLabel}::${sizeLabel}::${loadBoxKey}`;
      const current = partialGroups.get(groupKey) || {
        count: 0,
        totalKg: 0
      };
      current.count += 1;
      current.totalKg += qtyKg;
      partialGroups.set(groupKey, current);
