        if (totalQtyKg <= 0.001) return;
        const baseBatch = entries[0]?.batch || null;
        if (!baseBatch) return;
        const preferredVisualSlotNos = entries
          .map(({ batch }) => Math.max(0, Math.floor(Number(batch?.storageBoxVisualSlotNo) || 0)))
          .filter((visualSlotNo, entryIndex, slotNos) => visualSlotNo > 0 && slotNos.indexOf(visualSlotNo) === entryIndex)
          .sort((a, b) => a - b);
        let remainingQtyKg = totalQtyKg;
        const rebuiltBatches = [];
