            sizeLabel: String(resolvedBatch?.sizeLabel || card?.sizeLabel || '').trim() || '미측정',
            qtyKg: Math.max(0, Number(resolvedBatch?.qty) || Number(card?.qtyKg) || 0),
            life: Math.max(0, Number(resolvedBatch?.life) || 0),
