      const capacityKgPerUnit = Math.max(0, Number(storageCapacityKgPerUnitOfFacility(selectedField, facilityKey)) || 0);
      const supportsPalletSlots = isHarvestPalletFacility(facilityKey);
      const palletSlotsPerUnit = supportsPalletSlots ? harvestPalletSlotCountPerUnitOfFacility(selectedField, facilityKey) : 0;
      const totalPalletSlotCount = supportsPalletSlots ? harvestPalletSlotCountOfFacility(selectedField, facilityKey) : 0;
      const savedSlotsRaw = Array.isArray(facilityStorageHarvestSlotByFacility?.[facilityKey]) ? facilityStorageHarvestSlotByFacility[facilityKey] : [];
      const storedHarvestSlotsByNo = harvestStoredPalletSlotsByFacility?.[facilityKey] || {};
