    const facilityKey = String(facilityKeyRaw || '').trim();
    const planKey = String(planKeyRaw || '').trim();
    const plan = HOME_LIVING_INTERNET_PLAN_BY_KEY[planKey] || null;
    if (!facilityKey || !plan) return;
    const facilityRow = housingViewFacilityRows.find((row) => String(row?.key || '') === facilityKey) || null;
    if (!facilityRow) {
      setGameAlertMessage('현재 토지에 인터넷을 설치할 하우징이 없습니다.');
      return;
    }
    setGame((prev) => {
      if (!prev) return prev;
      const selectedIndex = Math.max(0, Math.floor(Number(prev.selectedField) || 0));
      const currentField = prev.fields?.[selectedIndex];
      if (!currentField || fieldFacilityCountOf(currentField, facilityKey) <= 0) return prev;
      const existing = normalizeHousingInternetContract(currentField?.housingInternetContractsByFacilityKey?.[facilityKey] || {});
      if (existing?.planKey === planKey) {
        const status = housingInternetContractStatusOf(existing, prev.day);
        setGameAlertMessage(`${facilityRow.name}은 이미 ${plan.name} 상태입니다. ${status.label}`);
        return prev;
      }
      const isPlanChange = Boolean(existing && housingInternetContractStatusOf(existing, prev.day).installed);
      const installFee = isPlanChange ? 0 : Math.max(0, Math.floor(Number(plan.installFee) || 0));
      if ((Number(prev.money) || 0) < installFee) {
        setGameAlertMessage(`설치비가 부족합니다. 필요 금액 ${won(installFee)}`);
        return prev;
      }
      const day = Math.max(0, Math.floor(Number(prev.day) || 0));
      const nextContract = {
        planKey,
        provider: '하우넷',
        requestedDay: day,
        installCompleteDay: isPlanChange ? day : day + 1,
        installedDay: isPlanChange ? day : day + 1,
        monthlyFee: Math.max(0, Math.floor(Number(plan.monthlyFee) || 0))
      };
      const nextFields = Array.isArray(prev.fields) ? [...prev.fields] : [];
      const nextContractMap = {
        ...(currentField.housingInternetContractsByFacilityKey || {}),
        [facilityKey]: nextContract
      };
      nextFields[selectedIndex] = {
        ...currentField,
        housingInternetContractsByFacilityKey: nextContractMap
      };
      const actionText = isPlanChange ? '인터넷 요금제 변경' : '인터넷 설치 신청';
      return {
        ...prev,
        money: Math.max(0, Math.floor((Number(prev.money) || 0) - installFee)),
        fields: nextFields,
        logs: pushDiary(
          prev,
          `${actionText}: ${facilityRow.name} / ${plan.name}${installFee > 0 ? ` / 설치비 ${won(installFee)}` : ''} / 월 ${won(plan.monthlyFee)}`
        )
      };
    });
