    const trees = clamp(Number(treeDraft) || 0, 1, Math.min(remainCapacity, stock, bindingStock, maxByFuel));
    const laborNeed = trees * laborPerTree;
    if (game.labor < laborNeed) {
      setPendingLaborConfirm({
        kind: 'plant',
        cropKey: targetCrop,
        needed: laborNeed,
        available: game.labor,
        requestedTrees: trees,
        source: WORK_SOURCE.work
      });
      return;
    }
    setGame((prev) => {
      const fields = [...prev.fields];
      const key = SEEDLING_KEY_BY_CROP[targetCrop];
      const field = fields[prev.selectedField];
      const fieldRemain = Math.max(0, fieldPlantableTreeCapacityByTrellis(field) - (field.trees || 0));
      const qty = seedlingTotalStockInFieldSourcesOf(prev, field, key);
      const bindingQty = plantBindingStockOf(prev, field, selectedPlantBindingKey);
      if (qty < trees) return prev;
      if (bindingQty <= 0) return prev;
      if (fieldRemain <= 0) return prev;
      if (usingExcavator && !Array.isArray(field?.machineParkingSlots)) return prev;
      if (usingExcavator && !field.machineParkingSlots.includes(excavatorInstanceId)) return prev;
      const currentFuel = usingExcavator
        ? Math.max(0, machineFuelLitersOfInstance(prev, excavatorInstanceId, selectedPlantingExcavatorInstance?.item))
        : 0;
      const maxByFuelInPrev = usingExcavator
        ? Math.floor(currentFuel / PLANT_EXCAVATOR_FUEL_USE_LITERS_PER_TREE)
        : Number.MAX_SAFE_INTEGER;
      const addTrees = Math.min(trees, fieldRemain, bindingQty, maxByFuelInPrev);
      if (addTrees <= 0) return prev;
      const nextLaborNeed = addTrees * laborPerTree;
      if (prev.labor < nextLaborNeed) return prev;
      const consumedSeedlings = consumeSeedlingsFromFieldSources(prev, field, key, addTrees);
      if (!consumedSeedlings.ok) return prev;
      const consumedBinding = consumePlantBindingFromFieldSources(
        {
          ...prev,
          inventory: consumedSeedlings.nextInventory,
          vehicleCargoByInstance: consumedSeedlings.nextVehicleCargoByInstance,
          bindingOpenRemain: prev.bindingOpenRemain || {}
        },
        field,
        selectedPlantBindingKey,
        addTrees
      );
      if (!consumedBinding.ok) return prev;
      const fuelUsed = usingExcavator ? (addTrees * PLANT_EXCAVATOR_FUEL_USE_LITERS_PER_TREE) : 0;
      const nextMachineFuelByInstance = usingExcavator
        ? {
          ...(prev.machineFuelByInstance || {}),
          [excavatorInstanceId]: Math.max(0, currentFuel - fuelUsed)
        }
        : prev.machineFuelByInstance;
      const nextTrees = (field.trees || 0) + addTrees;
      const isFirstPlanting = !field.cropId;
      fields[prev.selectedField] = {
        ...field,
        cropId: field.cropId || targetCrop,
        plantedDay: field.plantedDay || prev.day,
        lastHarvestYear: null,
        trees: nextTrees,
        plantLots: [...normalizePlantLotsForField(field), {
          id: `${targetCrop}-${prev.day}-${Date.now()}`,
          cropId: targetCrop,
          plantedDay: prev.day,
          trees: addTrees
        }],
        fruitLoadPerTree: isFirstPlanting ? 0 : (Number(field?.fruitLoadPerTree) || 0),
        fruitLoadReductionByAge: isFirstPlanting ? {} : (field.fruitLoadReductionByAge || {}),
        winterPruningModeByAge: isFirstPlanting ? {} : (field.winterPruningModeByAge || {}),
        winterPruningFruitLoadAdjustByAge: isFirstPlanting ? {} : (field.winterPruningFruitLoadAdjustByAge || {}),
        winterPruningEffectYear: isFirstPlanting ? 0 : Math.max(0, Number(field?.winterPruningEffectYear) || 0),
        pruningSealNeedByAge: isFirstPlanting ? {} : (field.pruningSealNeedByAge || {}),
        pruningSealantKeyByAge: isFirstPlanting ? {} : (field.pruningSealantKeyByAge || {}),
        pruningSealEffectYear: isFirstPlanting ? 0 : Math.max(0, Number(field?.pruningSealEffectYear) || 0),
        pollinationFruitLoadBonusByAge: isFirstPlanting ? {} : (field.pollinationFruitLoadBonusByAge || {}),
        pollinationFruitLoadBonus: isFirstPlanting ? 0 : clamp(Number(field?.pollinationFruitLoadBonus) || 0, 0, POLLINATION_FRUIT_LOAD_BONUS_MAX),
        ageTaskWorkedTreesByTask: isFirstPlanting ? {} : (field.ageTaskWorkedTreesByTask || {}),
        quality: field.cropId ? field.quality : 0,
        note: '식재 완료'
      };
      return {
        ...prev,
        labor: Math.max(0, prev.labor - nextLaborNeed),
        fields,
        inventory: consumedBinding.nextInventory,
        seedlingExpiryByKey: consumedSeedlings.nextSeedlingExpiryByKey,
        vehicleCargoByInstance: consumedBinding.nextVehicleCargoByInstance,
        bindingOpenRemain: consumedBinding.nextBindingOpenRemain,
        machineFuelByInstance: nextMachineFuelByInstance,
        logs: pushDiary(
          prev,
          `식재: ${CROPS[targetCrop].name} +${addTrees}주 (총 ${nextTrees}주, 노동력 -${nextLaborNeed} / ${selectedPlantBindingItemName} -${addTrees}개${usingExcavator ? ` / 굴삭기 연료 -${fuelUsed.toFixed(2)}L` : ''})`
        )
      };
    });
