    const normalizedTaskKey = isWinterPruningTaskKey(taskKey)
      ? WINTER_PRUNING_LIGHT_TASK_KEY
      : taskKey;
    const winterPruningMode = winterPruningModeFromTaskKey(taskKey);
    const pruningSealNeedByAge = normalizedTaskKey === PRUNING_SEAL_TASK_KEY
