        nextVehicleCargoByInstanceByTask = consumedFilm.nextVehicleCargoByInstance;
        nextReflectiveFilmOpenRemain = consumedFilm.nextOpenRemain;
        reflectiveFilmOpenedRolls = Math.max(0, Number(consumedFilm.openedUnits) || 0);
