        if (selectedReflectiveFilmCollectTransportInstanceId && reflectiveFilmCollectedMeters > 0) {
          const currentCargoMeters = Math.max(0, Number(nextReflectiveFilmCargoMetersByInstance?.[selectedReflectiveFilmCollectTransportInstanceId]) || 0);
          nextReflectiveFilmCargoMetersByInstance[selectedReflectiveFilmCollectTransportInstanceId] = currentCargoMeters + reflectiveFilmCollectedMeters;
          const cargoByKey = { ...(nextVehicleCargoByInstanceByTask?.[selectedReflectiveFilmCollectTransportInstanceId] || {}) };
          cargoByKey[COLLECTED_REFLECTIVE_FILM_ITEM_KEY] = Math.max(0, Number(cargoByKey?.[COLLECTED_REFLECTIVE_FILM_ITEM_KEY]) || 0) + reflectiveFilmCollectedMeters;
          nextVehicleCargoByInstanceByTask[selectedReflectiveFilmCollectTransportInstanceId] = normalizeCargoByItemKey(cargoByKey);
        }
