            cargoByKey[BRICK_ITEM_KEY] = Math.max(0, Number(cargoByKey?.[BRICK_ITEM_KEY]) || 0) + reflectiveFilmRecoveredBrickUnits;
            nextVehicleCargoByInstanceByTask[selectedReflectiveFilmCollectTransportInstanceId] = normalizeCargoByItemKey(cargoByKey);
