    const firstPoint = townMoveDrawDraftPoints[0];
    if (!viewportEl || !firstPoint) return false;
    const rect = viewportEl.getBoundingClientRect();
    const viewportW = Math.max(320, Number(townMoveMapViewportSize?.width) || Math.round(rect.width) || 960);
    const viewportH = Math.max(320, Number(townMoveMapViewportSize?.height) || Math.round(rect.height) || 620);
    const pxPerKm = townMoveMapPxPerKm();
    const cx = Number(townMoveMapCenter?.x) || 0;
    const cy = Number(townMoveMapCenter?.y) || 0;
