    if (!facilityStorageCarrierOnlyMode || !facilityStorageSelectedCarrier) return;
    const sourceCarrierId = String(facilityStorageSelectedCarrier?.id || '');
    if (!sourceCarrierId) return;
    const candidateTargetId = sourceCarrierId === MAP_TRANSFER_PERSONAL_CARRIER_ID
      ? String(facilityStorageAnchorCarrierId || '')
      : MAP_TRANSFER_PERSONAL_CARRIER_ID;
