    const vehicleLaborNeed = vehicleMoveLaborCost(moveDistanceKm);
    const overloadProfile = carrierOverloadProfileOfMachine(game, selectedVehicle);
    const adjustedLaborNeed = roundLabor(vehicleLaborNeed + Math.max(0, Number(overloadProfile?.laborAdd) || 0));
