  function moveSecondaryCarrierItemToSelectedCarrier(row, requestedQty = 1) {
    if (!facilityStorageCarrierOnlyMode || !facilityStorageSelectedCarrier || !facilityStorageSecondaryCarrier) return;
    const sourceCarrierId = String(facilityStorageSecondaryCarrier?.id || '');
    const targetCarrierId = String(facilityStorageSelectedCarrier?.id || '');
    if (!sourceCarrierId || !targetCarrierId || sourceCarrierId === targetCarrierId) return;
    const targetCarrier = facilityStorageSelectedCarrier;
    if (!targetCarrier || (Number(targetCarrier?.item?.payloadKg) || 0) <= 0) {
      window.alert('옮길 대상 적재함을 찾지 못했습니다.');
      return;
    }
    const itemKey = String(row?.itemKey || '');
    const normalizedItemKey = normalizeFuelContainerKey(itemKey) || itemKey;
    const sourceFuelKey = String(row?.sourceFuelKey || '');
    const fuelSourceScope = String(row?.fuelSourceScope || 'vehicle');
    const storedLitersPerCan = floorLitersToStep(row?.storedLitersPerCan);
    const rowQty = Math.max(0, Number(row?.qty) || 0);
    const moveQty = Math.max(1, Math.floor(Number(requestedQty) || 1));
    if (!itemKey || rowQty <= 0) return;
    const loadBlockedMessage = validateCarrierLoadRule({
      carrier: targetCarrier,
      carrierCargoByKey: game?.vehicleCargoByInstance?.[targetCarrierId] || {},
      itemKey,
      itemLike: itemMetaByKey?.[itemKey] || row || null,
      itemCategory: String(itemCategoryByKey?.[itemKey] || '')
    });
    if (loadBlockedMessage) {
      window.alert(loadBlockedMessage);
      return;
    }
    setGame((prev) => {
      const sourceCargoQty = Math.max(0, Number(prev?.vehicleCargoByInstance?.[sourceCarrierId]?.[itemKey]) || 0);
      if (sourceCargoQty <= 0) return prev;
      let qtyToMove = Math.max(0, Math.min(moveQty, rowQty, sourceCargoQty));
      if (qtyToMove <= 0) return prev;
      const targetPayloadKg = Math.max(0, Number(targetCarrier?.item?.payloadKg) || 0);
      const itemWeightKg = Math.max(0, Number(itemMetaByKey?.[itemKey]?.weightKg) || 0);
      const targetCargo = prev?.vehicleCargoByInstance?.[targetCarrierId] || {};
      const targetCurrentLoadKg = Object.entries(targetCargo).reduce((sum, [targetItemKey, targetQty]) => {
        const safeQty = Math.max(0, Number(targetQty) || 0);
        if (safeQty <= 0) return sum;
        const weightKg = Math.max(0, Number(itemMetaByKey?.[String(targetItemKey || '')]?.weightKg) || 0);
        return sum + (weightKg * safeQty);
      }, 0);
      const remainKg = Math.max(0, carrierMaxAllowedLoadKg(targetPayloadKg) - targetCurrentLoadKg);
      if (itemWeightKg > 0) {
        qtyToMove = Math.max(0, Math.min(qtyToMove, Math.floor(remainKg / itemWeightKg)));
        if (qtyToMove <= 0) return prev;
      }
      let nextFuelStorageByContainer = { ...(prev.fuelStorageByContainer || {}) };
      let nextVehicleFuelStorageByInstance = normalizeVehicleFuelStorageByInstance(prev.vehicleFuelStorageByInstance || {});
      if (sourceFuelKey && storedLitersPerCan > 0) {
        const litersToMove = floorLitersToStep(storedLitersPerCan * qtyToMove);
        if (litersToMove > 0) {
          if (fuelSourceScope.startsWith('global')) {
            const consumed = consumeStoredFuelLitersExactFromContainer(
              nextFuelStorageByContainer,
              sourceFuelKey,
              normalizedItemKey,
              litersToMove
            );
            if (consumed.consumedLiters <= 0) return prev;
            nextFuelStorageByContainer = consumed.nextFuelStorageByContainer;
            const targetFuelByContainer = normalizeFuelStorageByContainer(nextVehicleFuelStorageByInstance[targetCarrierId] || {});
            nextVehicleFuelStorageByInstance[targetCarrierId] = addStoredFuelLitersToContainer(
              targetFuelByContainer,
              normalizedItemKey,
              sourceFuelKey,
              consumed.consumedLiters
            );
          } else {
            const sourceFuelByContainer = normalizeFuelStorageByContainer(nextVehicleFuelStorageByInstance[sourceCarrierId] || {});
            const consumed = consumeStoredFuelLitersExactFromContainer(
              sourceFuelByContainer,
              sourceFuelKey,
              normalizedItemKey,
              litersToMove
            );
            if (consumed.consumedLiters <= 0) return prev;
            if (Object.keys(consumed.nextFuelStorageByContainer || {}).length > 0) {
              nextVehicleFuelStorageByInstance[sourceCarrierId] = consumed.nextFuelStorageByContainer;
            } else {
              delete nextVehicleFuelStorageByInstance[sourceCarrierId];
            }
            const targetFuelByContainer = normalizeFuelStorageByContainer(nextVehicleFuelStorageByInstance[targetCarrierId] || {});
            nextVehicleFuelStorageByInstance[targetCarrierId] = addStoredFuelLitersToContainer(
              targetFuelByContainer,
              normalizedItemKey,
              sourceFuelKey,
              consumed.consumedLiters
            );
          }
        }
      }
      const nextVehicleCargoByInstance = { ...(prev.vehicleCargoByInstance || {}) };
      const sourceCargo = { ...(nextVehicleCargoByInstance[sourceCarrierId] || {}) };
      sourceCargo[itemKey] = Math.max(0, Number(sourceCargo[itemKey]) || 0) - qtyToMove;
      if ((sourceCargo[itemKey] || 0) <= 0) delete sourceCargo[itemKey];
      if (Object.keys(sourceCargo).length > 0) {
        nextVehicleCargoByInstance[sourceCarrierId] = sourceCargo;
      } else {
        delete nextVehicleCargoByInstance[sourceCarrierId];
      }
      const targetCargoNext = { ...(nextVehicleCargoByInstance[targetCarrierId] || {}) };
      targetCargoNext[itemKey] = Math.max(0, Number(targetCargoNext[itemKey]) || 0) + qtyToMove;
      nextVehicleCargoByInstance[targetCarrierId] = targetCargoNext;
      return {
        ...prev,
        vehicleCargoByInstance: nextVehicleCargoByInstance,
        fuelStorageByContainer: nextFuelStorageByContainer,
        vehicleFuelStorageByInstance: nextVehicleFuelStorageByInstance
      };
    });
    setFacilityUnloadQtyByKey((prev) => {
      const next = { ...(prev || {}) };
      delete next[`secondary-${String(row?.rowKey || row?.itemKey || '')}`];
      return next;
    });
  }
