  const selectedPestProfile = normalizePestProfile(selectedField?.pestProfile, Number(selectedField?.pest ?? 10));
  const selectedDiseaseProfile = normalizeDiseaseProfile(selectedField?.diseaseProfile, Number(selectedField?.pest ?? 10));
