  const pestProfileWeightedTotal = weightedProfileValue(selectedPestProfile, PEST_PROFILE_WEIGHT, PEST_PROFILE_KEYS);
  const diseaseProfileWeightedTotal = weightedProfileValue(selectedDiseaseProfile, DISEASE_PROFILE_WEIGHT, DISEASE_PROFILE_KEYS);
