                            const isBrickCoatingTaskCard = task.key === BRICK_COATING_TASK_KEY;
                            const isBrickCollectionTaskCard = task.key === BRICK_COLLECTION_TASK_KEY;
                            const isAppleContainerCoatingTaskCard = task.key === APPLE_CONTAINER_COATING_TASK_KEY;
                            const isAppleContainerCollectionTaskCard = task.key === APPLE_CONTAINER_COLLECTION_TASK_KEY;
                            const brickStockUnitsForTask = isBrickCoatingTaskCard
