                            const appleContainerRequiredUnitsForTask = (
                              isAppleContainerCoatingTaskCard || isAppleContainerCollectionTaskCard
                            )
                              ? appleContainerRequiredUnitsOfField(selectedField, game.day)
                              : 0;
                            const appleContainerAppliedUnitsForTask = (
                              isAppleContainerCoatingTaskCard || isAppleContainerCollectionTaskCard
                            )
                              ? appleContainerAppliedUnitsOfField(selectedField)
                              : 0;
                            const selectedAppleContainerItemKeyForTask = isAppleContainerCoatingTaskCard
