                            const selectedTaskTreeAccessKey = String(taskTreeAccessChoice?.treeAccessEquipmentKey || '');
                            const selectedCleanupMoveAssistNameForTask = cleanupMoveAssistOptionsForTask.find((item) => item.key === selectedTaskTreeAccessKey)?.name || '미선택';
                            const taskTreeAccessUnitOptions = selectedTaskTreeAccessKey
